    // -----------------------------------------------------------------------
    // /sound
    // -----------------------------------------------------------------------

    /// A shell whose `/sound` starts `on` or not, and saves into `settings`.
    fn sounding(rows: u16, on: bool, settings: Option<std::path::PathBuf>) -> Fixture {
        let mut shell = shell(rows, 80);
        shell.sound = Sound::new(crate::config::Notifications::both(on), settings);
        shell
    }

    /// A profile of the case's own, and the settings file in it.
    fn profile() -> (tempfile::TempDir, std::path::PathBuf) {
        let home = tempfile::tempdir().expect("a home");
        let path = home.path().join(".xfx").join("settings.json");
        (home, path)
    }

    /// Waits for `path` to hold `expected`, or fails the case: the save is on
    /// a thread of its own.
    fn saved_as(path: &std::path::Path, expected: serde_json::Value) {
        let deadline = Instant::now() + Duration::from_secs(10);
        loop {
            let read = std::fs::read_to_string(path)
                .ok()
                .and_then(|text| serde_json::from_str::<serde_json::Value>(&text).ok());
            if read.as_ref() == Some(&expected) {
                return;
            }
            assert!(Instant::now() < deadline, "the file holds {read:?}");
            std::thread::sleep(Duration::from_millis(5));
        }
    }

    /// The notice a save that failed settles into, waited for.
    fn save_settled(shell: &mut Fixture) -> Vec<String> {
        let deadline = Instant::now() + Duration::from_secs(10);
        loop {
            shell.settle_band(Instant::now());
            let released = shell.released();
            if !released.is_empty() {
                return released;
            }
            assert!(Instant::now() < deadline, "the save never said how it went");
            std::thread::sleep(Duration::from_millis(5));
        }
    }

    #[test]
    fn sound_toggles_and_sets_and_answers_with_upstreams_notice() {
        // `fx-sound-40x120-{bare,on,off,bare2}.txt` from a session started
        // off: `* sound: on`, `on`, `off`, and a bare toggle from off is `on`
        // again -- every one a neutral notice, no echo, nothing saved said.
        let (_home, path) = profile();
        let mut shell = sounding(24, false, Some(path.clone()));
        for (line, level) in [
            ("/sound", "on"),
            ("/sound on", "on"),
            ("/sound off", "off"),
            ("/sound", "on"),
            ("/sound", "off"),
            ("/sound  on ", "on"),
        ] {
            shell.route_bytes(line.as_bytes());
            shell.route_bytes(b"\r");
            // Said once saved, as upstream saves before it answers: the exit's
            // view waits for the write.
            assert_eq!(
                shell.released(),
                said(notice::Notice::neutral("sound", level)),
                "{line:?}"
            );
            assert_eq!(
                shell.sound.notifications(),
                crate::config::Notifications::both(level == "on"),
                "{line:?}"
            );
        }
        assert!(shell.sent.try_recv().is_err(), "/sound reached the runtime");
        assert!(shell.editor.is_empty());
        // Both switches, in the file the next session reads.
        saved_as(
            &path,
            serde_json::json!({"notifications": {"turn_end": true, "attention_required": true}}),
        );
        // And a successful save says nothing more.
        shell.settle_band(Instant::now());
        assert!(shell.released().is_empty());
    }

    #[test]
    fn sound_with_a_word_that_is_not_a_level_is_the_usage_line_and_moves_nothing() {
        // `fx-sound-40x120-bogus.txt`: `✗ usage: /sound [on|off|max]`, no
        // topic -- here without the `max` this build does not have, which is
        // why `max` itself is one of the refusals.
        let (_home, path) = profile();
        let mut shell = sounding(24, true, Some(path.clone()));
        for line in ["/sound bogus", "/sound max", "/sound ON", "/sound on off"] {
            shell.route_bytes(line.as_bytes());
            shell.route_bytes(b"\r");
            assert_eq!(
                shell.document(),
                said(notice::Notice::error("", "usage: /sound [on|off]")),
                "{line:?}"
            );
            assert_eq!(
                shell.sound.notifications(),
                crate::config::Notifications::both(true),
                "{line:?} moved the switches"
            );
        }
        shell.settle_band(Instant::now());
        assert!(!path.exists(), "a refused level was saved");
    }

    #[test]
    fn a_save_that_failed_says_so_before_the_level() {
        // `reportUserSettingsFailure` (`session_commands.zig:110-133`): an
        // error under `sound`, saying the switch is in force anyway -- and
        // before the level, as upstream saves before it answers
        // (`handleNotificationsCommand`, `app_commands.zig:4014-4027`). The
        // save is on its own thread, so the level waits for it.
        let (home, path) = profile();
        crate::profile_home::made(path.parent().expect("a profile"));
        std::fs::write(&path, "{ not json").expect("seed");
        let mut shell = sounding(24, false, Some(path.clone()));
        shell.route_bytes(b"/sound\r");
        let said_rows = save_settled(&mut shell);
        let failed = joined(&said_rows);
        assert!(
            failed.starts_with(
                "\u{2717} sound: active for this process but not saved to user settings ("
            ),
            "{failed}"
        );
        assert!(failed.contains("not valid JSON"), "{failed}");
        assert!(failed.ends_with("* sound: on"), "{failed}");
        assert_eq!(std::fs::read(&path).expect("read"), b"{ not json");
        // The switch is in force all the same.
        assert_eq!(
            shell.sound.notifications(),
            crate::config::Notifications::both(true)
        );
        drop(home);
    }

    #[test]
    fn a_save_with_nowhere_to_go_is_said_before_the_level() {
        // The one failure known before the level is said, so it is said in
        // upstream's order. A shell a test built has no settings file.
        let mut shell = shell(24, 80);
        let before = shell.sound.notifications();
        shell.route_bytes(b"/sound\r");
        let level = if before.turn_end { "off" } else { "on" };
        let said_rows = shell.document();
        assert_eq!(
            joined(&said_rows),
            format!(
                "\u{2717} sound: active for this process but not saved to user settings \
                 (no home directory is set) * sound: {level}"
            )
        );
    }

    /// One whole turn: started, answered, ended, and presented to the end.
    fn a_whole_turn(shell: &mut Fixture, failure: Option<&str>) {
        let started = turn_running(shell, b"ask something\r");
        shell.apply(UiEvent::Delta("an answer".to_string()));
        shell.apply(UiEvent::TurnEnded {
            failure: failure.map(str::to_string),
        });
        let mut now = started;
        while shell.pacer.pending() > 0 || !shell.marks.is_empty() {
            now += Duration::from_millis(TICK_MILLIS);
            shell.settle_band(now);
        }
        shell.settle_band(now);
    }

    #[test]
    fn a_turn_that_ends_rings_once_its_answer_is_on_the_screen() {
        // `postTurnEndHandler` and the presentation queue
        // (`hooks/notifications.zig:74-118`, `:224-240`): a bell for a turn
        // that answered and for one that failed, and not before the reader has
        // been given the end of the answer.
        for failure in [None, Some("the provider said no")] {
            let mut shell = sounding(24, true, None);
            let started = turn_running(&mut shell, b"ask something\r");
            shell.apply(UiEvent::Delta(
                "a long enough answer to be paced".to_string(),
            ));
            shell.apply(UiEvent::TurnEnded {
                failure: failure.map(str::to_string),
            });
            if failure.is_none() {
                assert!(shell.pacer.pending() > 0, "nothing was left to present");
                shell.settle_band(started);
                assert_eq!(shell.take_bells(), 0, "rang ahead of the answer");
            }
            let mut now = started;
            while shell.pacer.pending() > 0 || !shell.marks.is_empty() {
                now += Duration::from_millis(TICK_MILLIS);
                shell.settle_band(now);
            }
            shell.settle_band(now);
            assert_eq!(shell.take_bells(), 1, "{failure:?}");
            assert_eq!(shell.take_bells(), 0, "{failure:?} rang twice");
        }
    }

    #[test]
    fn a_turn_ends_in_silence_when_sound_is_off_or_the_user_stopped_it() {
        let mut quiet = sounding(24, false, None);
        a_whole_turn(&mut quiet, None);
        assert_eq!(quiet.take_bells(), 0, "sound off rang");

        // Ctrl-C stops the turn: its end is the user's, as upstream's
        // `.interrupted => return` has it -- and the next turn rings again.
        let mut shell = sounding(24, true, None);
        let started = turn_running(&mut shell, b"ask something\r");
        shell.route_bytes(&[0x03]);
        shell.apply(UiEvent::TurnEnded {
            failure: Some("the turn was cancelled".to_string()),
        });
        shell.settle_band(started + Duration::from_secs(5));
        assert_eq!(shell.take_bells(), 0, "an interrupted turn rang");
        a_whole_turn(&mut shell, None);
        assert_eq!(shell.take_bells(), 1, "the interrupt outlived its turn");
    }

    #[test]
    fn work_that_ran_no_turn_rings_nothing() {
        // `/model`, `/setup` and a catalog load end with the same event and
        // ran no turn: no summary, and no bell.
        let mut shell = sounding(24, true, None);
        shell.apply(UiEvent::TurnEnded { failure: None });
        shell.settle_band(Instant::now());
        assert_eq!(shell.take_bells(), 0);
    }

    #[test]
    fn a_question_that_opens_rings_at_once() {
        // `dispatchAttentionRequired` for a permission prompt and for the
        // model's questions (`app_worker_runtime.zig:766-767`, `:1089-1097`),
        // and with no wait for the pacer: the turn is stopped on the user.
        let mut shell = sounding(24, true, None);
        turn_running(&mut shell, b"edit the notes\r");
        shell.apply(UiEvent::Approval(question(asked())));
        assert_eq!(shell.take_bells(), 1, "the permission prompt");

        let mut fixture = sounding(24, true, None);
        turn_running(&mut fixture, b"ask me\r");
        fixture.apply(UiEvent::Question(a_batch()));
        assert_eq!(fixture.take_bells(), 1, "the model's question");

        // On the other plane too: a change too large for the band.
        let mut wide = sounding(40, true, None);
        turn_running(&mut wide, b"edit the notes\r");
        wide.apply(UiEvent::Approval(question(asked_about_a_large_change())));
        assert_eq!(wide.screen_owner(), ScreenOwner::Alternate);
        assert_eq!(wide.take_bells(), 1, "the review on the other plane");
    }

    #[test]
    fn a_question_nobody_is_shown_or_sound_off_rings_nothing() {
        // A screen too small refuses the question on the user's behalf; there
        // is nobody to call.
        let mut small = sounding(10, true, None);
        turn_running(&mut small, b"edit the notes\r");
        small.apply(UiEvent::Approval(question(asked())));
        assert_eq!(small.geometry.panel, 0);
        assert_eq!(small.take_bells(), 0);

        let mut quiet = sounding(24, false, None);
        turn_running(&mut quiet, b"edit the notes\r");
        quiet.apply(UiEvent::Approval(question(asked())));
        assert_eq!(quiet.take_bells(), 0);
    }

    #[test]
    fn sound_moves_what_the_next_turn_does() {
        // The switch is in force from the keystroke: the turn after `/sound`
        // rings, and the one after `/sound off` does not.
        let mut shell = sounding(24, false, None);
        shell.route_bytes(b"/sound\r");
        a_whole_turn(&mut shell, None);
        assert_eq!(shell.take_bells(), 1);
        shell.route_bytes(b"/sound off\r");
        a_whole_turn(&mut shell, None);
        assert_eq!(shell.take_bells(), 0);
    }

    #[test]
    fn a_command_that_takes_nothing_runs_only_when_nothing_follows_it() {
        // `fx-basic-40x120-version-trailing-space.txt`, in its order: the two
        // with an argument are unknown commands, the one with a trailing
        // space runs -- and two notices in a row share one blank row.
        let mut shell = shell(24, 80);
        shell.route_bytes(b"/help extra\r");
        shell.route_bytes(b"/version now\r");
        shell.route_bytes(b"/version \r");
        let unknown = notice::Notice::error("command", "Unknown command. Try /help.");
        assert_eq!(
            shell.document(),
            [
                said(unknown.clone()),
                said(unknown),
                said(notice::Notice::neutral(
                    "version",
                    crate::build_info().version()
                )),
            ]
            .concat()
        );
        assert!(
            shell.sent.try_recv().is_err(),
            "a refused command reached the runtime"
        );
        assert!(
            shell.editor.is_empty(),
            "the refused line stayed in the composer"
        );
    }

    /// A snapshot every field of which this file spells, so the case that
    /// reads it back can say the whole notice literally.
    fn a_status(history_turns: u64, grants: u64) -> crate::output::StatusSnapshot {
        let home = tempfile::tempdir().expect("a home");
        let workspace = tempfile::tempdir().expect("a workspace");
        let mut snapshot = crate::output::StatusSnapshot::new(
            &config(home.path(), workspace.path()),
            crate::build_info(),
            crate::output::SessionFacts::default(),
        );
        snapshot.model = "acme/model-9".to_string();
        snapshot.provider = "gateway".to_string();
        snapshot.provider_url = None;
        snapshot.provider_rejected = None;
        snapshot.version = format!("{} (debug 2026-11-10-0019-0123456789ab)", crate::VERSION);
        snapshot.build_channel = "debug".to_string();
        snapshot.build_revision = Some("0123456789ab".to_string());
        snapshot.auth = "AI_GATEWAY_API_KEY".to_string();
        snapshot.auth_refreshable = false;
        snapshot.auth_help = None;
        snapshot.permission_mode = "auto".to_string();
        snapshot.workspace = "/w/work".to_string();
        snapshot.history_turns = history_turns;
        snapshot.session_permission_grants = grants;
        snapshot.agent_step_limit = 0;
        snapshot
    }

    // -----------------------------------------------------------------------
    // `/permissions` and Shift-Tab
    // -----------------------------------------------------------------------

    /// A 40x120 shell in `mode`, whose person has or has not been shown the
    /// full-access warning, and the runtime end of the channel a change to the
    /// session's authority goes down.
    fn permissions_shell(
        mode: PermissionMode,
        acknowledged: bool,
    ) -> (Fixture, UnboundedReceiver<Change>) {
        let home = tempfile::tempdir().expect("a home");
        let workspace = tempfile::tempdir().expect("a workspace");
        let mut config = config(home.path(), workspace.path());
        config.permission_mode = mode;
        config.yolo_acknowledged = acknowledged;
        let (work, sent, control, changes) = WorkHandle::detached_with_changes();
        let fixture = Fixture {
            shell: Shell::new(
                &config,
                crate::tui::layout::solve(40, 120, 1).expect("a band"),
                PALETTE,
                false,
                work,
            )
            .anchored(),
            sent,
            control,
        };
        (fixture, changes)
    }

    /// Every change the shell has handed the runtime so far, in order.
    fn changes_sent(changes: &mut UnboundedReceiver<Change>) -> Vec<Change> {
        std::iter::from_fn(|| changes.try_recv().ok()).collect()
    }

    /// One labelled line of an open bare `/permissions` panel at 120 columns:
    /// the value column is two columns, the longest label (`Configured
    /// rules`) and four (`cap/panels/new/fx-p5-panels-permissions-40x120-bare`).
    fn permissions_line(label: &str, value: &str) -> String {
        format!("  {label}{}{value}", " ".repeat(20 - label.len()))
    }

    /// One listed item of it, its bullet in the value column.
    fn permissions_item(text: &str) -> String {
        format!("{}\u{2022} {text}", " ".repeat(22))
    }

    /// The panel's three closing rows, as upstream writes them.
    fn permissions_how_to() -> [String; 3] {
        [
            permissions_line(
                "Change mode",
                "/permissions ask, auto, full-access, or reset",
            ),
            permissions_line(
                "Remember",
                "/permissions remember allow|deny <tool-name> <arguments-json>",
            ),
            permissions_line("Revoke", "/permissions revoke <rule-id>"),
        ]
    }

    #[test]
    fn a_bare_permissions_opens_upstreams_panel_and_changes_nothing() {
        // `cap/panels/new/fx-p5-panels-permissions-40x120-bare`, rows 3-14: a
        // rule, `Permissions`, a blank, the mode and each list's count, the
        // three ways to change them, a rule, `esc close` -- the composer and
        // the mode hint gone, nothing in the document.
        let (mut shell, mut changes) = permissions_shell(PermissionMode::Auto, true);
        shell.route_bytes(b"/permissions\r");
        assert!(shell.document().is_empty(), "it wrote to the document");
        assert_eq!(shell.geometry.input_rows(), 0, "the composer kept its row");
        let rows = shell.band_rows();
        let mut expected = vec![
            uncoloured(&divider(120)),
            "Permissions".to_string(),
            String::new(),
            permissions_line("Mode", "auto"),
            permissions_line("Configured rules", "none"),
            permissions_line("Session grants", "none"),
            permissions_line("Saved rules", "none"),
        ];
        expected.extend(permissions_how_to());
        expected.extend([uncoloured(&divider(120)), "esc close".to_string()]);
        assert_eq!(uncoloured_rows(&from_the_rule(&rows)), expected);
        assert_eq!(rows.last(), Some(&dim_hint("esc close")));
        assert!(changes_sent(&mut changes).is_empty());
        assert!(
            shell.sent.try_recv().is_err(),
            "it was handed to the runtime"
        );
        assert_eq!(shell.work.outstanding(), 0, "it took a place in the queue");
        // Shift-Tab is the panel's to swallow: the mode does not move
        // (`cap/panels/new/fx-p5-panels-keys-40x120-perm-btab`).
        shell.route_bytes(b"\x1b[Z");
        assert_eq!(shell.mode, PermissionMode::Auto);
        assert!(changes_sent(&mut changes).is_empty());
        // Escape closes it and leaves nothing behind (`-esc`); so does Enter.
        escape(&mut shell);
        assert!(shell.info_panel.is_none());
        assert!(shell.document().is_empty());
        // Blanks after the name are still bare (`std.mem.trim(u8, rest, " \t")`,
        // `app_commands.zig:590@481104fd`).
        shell.route_bytes(b"/permissions \t \r");
        assert_eq!(
            shell.info_panel.as_ref().map(info_panel::Panel::title),
            Some("Permissions")
        );
        shell.route_bytes(b"\r");
        assert!(shell.info_panel.is_none(), "Enter left the panel up");
        assert!(shell.document().is_empty());
        // Every other form keeps its path: a notice, and no panel.
        shell.route_bytes(b"/permissions bogus\r");
        assert!(shell.info_panel.is_none());
        assert_eq!(
            shell.document().first().map(String::as_str),
            Some("\u{2717} usage: /permissions [ask|auto|full-access|reset]")
        );
    }

    #[test]
    fn a_bare_permissions_lists_the_grants_the_runtime_published() {
        let (mut shell, _changes) = permissions_shell(PermissionMode::Ask, true);
        shell.work.publish_grants(vec![
            permissions::Granted {
                tool: "write_file".to_string(),
                target: "notes.md".to_string(),
            },
            permissions::Granted {
                tool: "terminal".to_string(),
                target: "ls in /w".to_string(),
            },
        ]);
        shell.route_bytes(b"/permissions\r");
        let shown = uncoloured_rows(&from_the_rule(&shell.band_rows()));
        assert_eq!(
            shown[3..9],
            [
                permissions_line("Mode", "ask"),
                permissions_line("Configured rules", "none"),
                permissions_line("Session grants", "2"),
                permissions_item("write_file \u{2192} notes.md"),
                permissions_item("terminal \u{2192} ls in /w"),
                permissions_line("Saved rules", "none"),
            ],
            "{shown:?}"
        );
    }

    #[test]
    fn an_open_permissions_panel_says_the_authority_as_it_moves_and_keeps_its_scroll() {
        // `collectInfoPanelFacts` on every tick (`main.zig:2884-2886@481104fd`),
        // on upstream's facts -- the mode, the grants, the configured rules --
        // and xfx's reset count: a reset taken from the live authority is
        // shown at once, before the runtime publishes again.
        let (mut shell, _changes) = permissions_shell(PermissionMode::Auto, true);
        shell.work.publish_grants(vec![permissions::Granted {
            tool: "write_file".to_string(),
            target: "a.txt".to_string(),
        }]);
        shell.route_bytes(b"/permissions\r");
        assert_eq!(panel_value(&shell, "Session grants").as_deref(), Some("1"));
        shell.route_bytes(b"\x1b[B");

        // Nothing moved: no rebuild.
        let now = Instant::now();
        shell.settle_band(now);
        let unmoved = shell.info_panel.clone();
        shell.settle_band(now);
        assert_eq!(shell.info_panel, unmoved);

        // A grant published as a turn ends.
        shell.work.publish_grants(vec![
            permissions::Granted {
                tool: "write_file".to_string(),
                target: "a.txt".to_string(),
            },
            permissions::Granted {
                tool: "terminal".to_string(),
                target: "ls in /w".to_string(),
            },
        ]);
        shell.settle_band(now);
        assert_eq!(panel_value(&shell, "Session grants").as_deref(), Some("2"));
        assert_ne!(
            shell.info_panel, unmoved,
            "the rebuild lost the scroll or the rows"
        );

        // A configured rule put in force from the profile's table.
        shell
            .work
            .rules()
            .replace(crate::permission::RuleSet::new(vec![
                crate::permission::ConfiguredRule::new(
                    "bash",
                    "git *",
                    crate::permission::RuleAction::Allow,
                ),
            ]));
        shell.settle_band(now);
        assert_eq!(
            panel_value(&shell, "Configured rules").as_deref(),
            Some("1")
        );

        // A reset taken from the live authority, the runtime not told yet:
        // no grant is in force, so none is listed, and the mode is ask.
        shell.choose_mode(Change::Reset, PermissionMode::Ask);
        shell.settle_band(now);
        assert_eq!(panel_value(&shell, "Mode").as_deref(), Some("ask"));
        assert_eq!(
            panel_value(&shell, "Session grants").as_deref(),
            Some("none")
        );
        assert!(shell.document().is_empty());
    }

    #[test]
    fn an_unreadable_saved_rule_store_opens_no_panel_and_says_why() {
        // Upstream's open fails with the read (`savedPermissionRules`'s `try`,
        // `session_commands.zig:388-400@481104fd`); xfx says why, as the
        // listing did, and shows no authority it could not read.
        let (_home, _workspace, rules, mut shell) = remembering_shell();
        std::fs::write(&rules, b"not json").expect("a broken store");
        shell.route_bytes(b"/permissions\r");
        assert!(shell.info_panel.is_none());
        let document = shell.document();
        assert!(
            document
                .first()
                .is_some_and(|row| row.starts_with("\u{2717} permissions: ")),
            "{document:?}"
        );
    }

    /// Keeps a rule for `display` in the saved-session store at `rules`, as a
    /// confirmed `remember` does, through the store's own transaction.
    fn keep_rule(rules: &std::path::Path, canonical: &[u8], display: &str) {
        use crate::permission::session_rules::{self, Decision, Event, KeyKind, RuleKey};
        let applied = session_rules::update(
            rules,
            &Event::Set {
                key: RuleKey::new(KeyKind::FileMutation, canonical.to_vec()).expect("a key"),
                display: display.to_string(),
                decision: Decision::Deny,
                expected: None,
            },
        )
        .expect("the store");
        assert!(
            matches!(applied, session_rules::Applied::Applied(_)),
            "{applied:?}"
        );
    }

    #[test]
    fn a_saved_rule_store_that_breaks_while_the_panel_is_up_closes_it() {
        // Review P-permissions-b item 1: the file alone is broken -- no mode,
        // grant, rule or reset moves -- and the open panel still sees it on
        // the next tick, closes, and says why.
        let (_home, _workspace, rules, mut shell) = remembering_shell();
        keep_rule(&rules, b"a", "write_file a.txt preimage=absent after=00");
        shell.route_bytes(b"/permissions\r");
        assert_eq!(panel_value(&shell, "Saved rules").as_deref(), Some("1"));
        std::fs::write(&rules, b"not json").expect("a broken store");
        shell.settle_band(Instant::now());
        assert!(shell.info_panel.is_none(), "rules it cannot read stayed up");
        assert!(
            shell
                .document()
                .first()
                .is_some_and(|row| row.starts_with("\u{2717} permissions: ")),
            "{:?}",
            shell.document()
        );
    }

    #[test]
    fn an_open_permissions_panel_follows_a_saved_rule_store_another_hand_changed() {
        // Review P-permissions-b item 1: another valid rule set, written with
        // nothing else moved, is the set the panel shows on the next tick.
        let (_home, _workspace, rules, mut shell) = remembering_shell();
        shell.route_bytes(b"/permissions\r");
        assert_eq!(panel_value(&shell, "Saved rules").as_deref(), Some("none"));
        keep_rule(&rules, b"b", "write_file b.txt preimage=absent after=11");
        shell.settle_band(Instant::now());
        assert_eq!(panel_value(&shell, "Saved rules").as_deref(), Some("1"));
        keep_rule(&rules, b"c", "write_file c.txt preimage=absent after=22");
        shell.settle_band(Instant::now());
        assert_eq!(panel_value(&shell, "Saved rules").as_deref(), Some("2"));
        let shown = uncoloured_rows(&shell.band_rows());
        assert!(
            shown.contains(&permissions_item(
                "2 deny write_file c.txt preimage=absent after=22"
            )),
            "{shown:?}"
        );
        // Nothing moved since: no rebuild.
        let unmoved = shell.info_panel.clone();
        shell.settle_band(Instant::now());
        assert_eq!(shell.info_panel, unmoved);
        assert!(shell.document().is_empty());
    }

    #[test]
    fn an_open_permissions_panel_whose_store_cannot_be_stamped_reads_it_again() {
        // Review P-permissions-c item 1: a stamp that cannot be taken says
        // nothing about the file, so two of them are no proof it held still.
        // The rows are shown as built under one (a `stat` that failed while
        // the read did not); with the store unreadable since, the next tick
        // reads it again, and closes.
        let (_home, _workspace, mut shell) = allowlist_shell();
        let file = shell.workspace.join("not-a-directory");
        std::fs::write(&file, b"x").expect("a file");
        // `<file>/permissions.json`: `stat` and `open` both say ENOTDIR,
        // which is neither absent nor readable, for any user.
        shell
            .work
            .publish_saved_rules(crate::permission::session_rules::path_in(&file));
        let (facts, ..) = shell.permissions_in_force();
        assert!(
            matches!(
                facts,
                info_panel::Facts::Permissions { ref store, .. } if store.is_unknown()
            ),
            "{facts:?}"
        );
        let rows = info_panel::permissions_rows(
            shell.mode,
            &crate::permission::RuleSet::default(),
            &[],
            &[],
        );
        shell.open_info_panel(info_panel::Panel::open(rows, facts));
        shell.settle_band(Instant::now());
        assert!(
            shell.info_panel.is_none(),
            "rules shown under a stamp that said nothing stayed up"
        );
        assert!(
            shell
                .document()
                .first()
                .is_some_and(|row| row.starts_with("\u{2717} permissions: ")),
            "{:?}",
            shell.document()
        );
    }

    #[cfg(unix)]
    #[test]
    fn a_saved_rule_store_that_turns_into_a_fifo_closes_the_panel_without_waiting() {
        // Review P-permissions-c item 2: a FIFO put at the store's path. Its
        // stamp moves, so the tick reads the store again on the thread that
        // holds the terminal; an open that waited for a writer would hold it
        // for as long as none came. A watchdog stands in for that writer after
        // ten seconds, so a regression fails here rather than hangs.
        let (_home, _workspace, rules, mut shell) = remembering_shell();
        keep_rule(&rules, b"a", "write_file a.txt preimage=absent after=00");
        shell.route_bytes(b"/permissions\r");
        assert_eq!(panel_value(&shell, "Saved rules").as_deref(), Some("1"));
        std::fs::remove_file(&rules).expect("the store gone");
        let status = crate::process::status(std::process::Command::new("mkfifo").arg(&rules))
            .expect("run mkfifo");
        assert!(status.success(), "mkfifo failed: {status:?}");

        let (done, finished) = std::sync::mpsc::channel::<()>();
        let rescued = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let watchdog = {
            let fifo = rules.clone();
            let rescued = std::sync::Arc::clone(&rescued);
            std::thread::spawn(move || {
                if finished.recv_timeout(Duration::from_secs(10)).is_err() {
                    rescued.store(true, std::sync::atomic::Ordering::SeqCst);
                    drop(std::fs::OpenOptions::new().write(true).open(&fifo));
                }
            })
        };
        shell.settle_band(Instant::now());
        let _ = done.send(());
        watchdog.join().expect("the watchdog");
        assert!(
            !rescued.load(std::sync::atomic::Ordering::SeqCst),
            "the tick waited for a writer on the FIFO"
        );
        assert!(shell.info_panel.is_none(), "a FIFO's rules stayed up");
        assert!(
            shell
                .document()
                .first()
                .is_some_and(|row| row.starts_with("\u{2717} permissions: ")),
            "{:?}",
            shell.document()
        );
    }

    #[cfg(unix)]
    #[test]
    fn a_store_replaced_by_another_of_the_same_size_and_time_is_read_again() {
        // Review P-permissions-c item 3: another valid store renamed over the
        // first, of the same length, the same mode and the same modification
        // time -- only the inode tells the two apart, and the panel follows.
        use crate::permission::session_rules::{Decision, KeyKind, Rule, RuleKey, State};
        use std::os::unix::fs::PermissionsExt;
        let (_home, _workspace, rules, mut shell) = remembering_shell();
        let store = |name: &str| State {
            next_generation: 2,
            rules: vec![Rule {
                id: 1,
                key: RuleKey::new(KeyKind::FileMutation, name.as_bytes().to_vec()).expect("a key"),
                display: format!("write_file {name}.txt preimage=absent after=00"),
                decision: Decision::Deny,
                generation: 1,
            }],
        };
        std::fs::write(&rules, store("a").encode()).expect("the first store");
        std::fs::set_permissions(&rules, std::fs::Permissions::from_mode(0o600))
            .expect("owner-only");
        shell.route_bytes(b"/permissions\r");
        assert!(
            uncoloured_rows(&shell.band_rows()).contains(&permissions_item(
                "1 deny write_file a.txt preimage=absent after=00"
            ))
        );

        let before = std::fs::metadata(&rules).expect("the first store");
        let staged = rules.with_extension("staged");
        let bytes = store("b").encode();
        assert_eq!(bytes.len() as u64, before.len(), "not the same size");
        std::fs::write(&staged, &bytes).expect("the second store");
        std::fs::set_permissions(&staged, std::fs::Permissions::from_mode(0o600))
            .expect("owner-only");
        std::fs::File::options()
            .write(true)
            .open(&staged)
            .and_then(|file| file.set_modified(before.modified().expect("an mtime")))
            .expect("the same mtime");
        std::fs::rename(&staged, &rules).expect("renamed over");
        let after = std::fs::metadata(&rules).expect("the second store");
        assert_eq!(
            (
                after.len(),
                after.modified().ok(),
                after.permissions().mode()
            ),
            (
                before.len(),
                before.modified().ok(),
                before.permissions().mode()
            )
        );

        shell.settle_band(Instant::now());
        let shown = uncoloured_rows(&shell.band_rows());
        assert!(
            shown.contains(&permissions_item(
                "1 deny write_file b.txt preimage=absent after=00"
            )),
            "the panel kept the store the rename replaced: {shown:?}"
        );
    }

    #[test]
    fn a_reset_alone_rebuilds_an_open_permissions_panel() {
        // Review P-permissions-b item 2: the mode and the grant count are the
        // same before and after, so only the reset count tells the panel the
        // grants it lists are not the ones in force.
        let (mut shell, _changes) = permissions_shell(PermissionMode::Ask, true);
        let grant = |target: &str| permissions::Granted {
            tool: "write_file".to_string(),
            target: target.to_string(),
        };
        shell.work.publish_grants(vec![grant("a.txt")]);
        shell.route_bytes(b"/permissions\r");
        assert!(uncoloured_rows(&shell.band_rows())
            .contains(&permissions_item("write_file \u{2192} a.txt")));
        shell.choose_mode(Change::Reset, PermissionMode::Ask);
        // The runtime, between pieces of work, publishes one grant made since
        // the reset: ask again, one grant again.
        shell.work.publish_grants(vec![grant("b.txt")]);
        shell.settle_band(Instant::now());
        let shown = uncoloured_rows(&shell.band_rows());
        assert!(
            shown.contains(&permissions_item("write_file \u{2192} b.txt")),
            "the panel kept the grant a reset took away: {shown:?}"
        );
        assert!(!shown.contains(&permissions_item("write_file \u{2192} a.txt")));
    }

    #[test]
    fn a_bare_permissions_panel_names_what_a_model_or_a_file_put_in_it() {
        // A grant's command is a model's text, a configured pattern a file's:
        // neither may carry an escape, a line break or a reordering character
        // onto the screen.
        let (mut shell, _changes) = permissions_shell(PermissionMode::Ask, true);
        shell.work.publish_grants(vec![permissions::Granted {
            tool: "terminal".to_string(),
            target: "printf '\u{1b}[2J'\necho \u{202e}fdsa in /w".to_string(),
        }]);
        shell
            .work
            .rules()
            .replace(crate::permission::RuleSet::new(vec![
                crate::permission::ConfiguredRule::new(
                    "bash",
                    "git\u{200b} *",
                    crate::permission::RuleAction::Deny,
                ),
            ]));
        shell.route_bytes(b"/permissions\r");
        let rows = shell.band_rows();
        assert!(
            !rows.iter().any(|row| uncoloured(row).contains('\u{1b}')
                || row.contains('\u{202e}')
                || row.contains('\u{200b}')),
            "{rows:?}"
        );
        let shown = uncoloured_rows(&from_the_rule(&rows));
        assert!(
            shown.contains(&permissions_item("deny bash \u{2192} git\\u{200B} *")),
            "{shown:?}"
        );
        assert!(
            shown.contains(&permissions_item(
                "terminal \u{2192} printf '\\u{001B}[2J'\\necho \\u{202E}fdsa in /w"
            )),
            "{shown:?}"
        );
    }

    /// A 40x120 shell over a profile the test keeps alive, so `/allowlist`
    /// has a file to write.
    fn allowlist_shell() -> (tempfile::TempDir, tempfile::TempDir, Fixture) {
        let home = tempfile::tempdir().expect("a home");
        let workspace = tempfile::tempdir().expect("a workspace");
        let config = config(home.path(), workspace.path());
        let (work, sent, control, _changes) = WorkHandle::detached_with_changes();
        let fixture = Fixture {
            shell: Shell::new(
                &config,
                crate::tui::layout::solve(40, 120, 1).expect("a band"),
                PALETTE,
                false,
                work,
            )
            .anchored(),
            sent,
            control,
        };
        (home, workspace, fixture)
    }

    #[test]
    fn an_allowlist_change_is_one_notice_and_in_force_for_the_next_decision() {
        use crate::permission::{ConfiguredRule, RuleAction};
        let (_home, _workspace, mut shell) = allowlist_shell();
        shell.route_bytes(b"/allowlist add command \"git *\"\r");
        assert_eq!(
            shell.document(),
            vec![
                "* allowlist: added command: \"git *\" (scope=local)".to_string(),
                String::new(),
            ]
        );
        // The handle every conversation decides with holds it now: the next
        // tool call is judged by it without a restart (trap (d)).
        assert_eq!(
            shell.work.rules().current().rules(),
            &[ConfiguredRule::new("bash", "git *", RuleAction::Allow)]
        );
        assert!(
            shell.sent.try_recv().is_err(),
            "nothing went to the runtime"
        );
        shell.route_bytes(b"/permissions\r");
        let shown = uncoloured_rows(&from_the_rule(&shell.band_rows()));
        assert_eq!(
            shown[3..7],
            [
                permissions_line("Mode", "auto"),
                permissions_line("Configured rules", "1"),
                permissions_item("allow bash \u{2192} git *"),
                permissions_line("Session grants", "none"),
            ],
            "{shown:?}"
        );
    }

    #[test]
    fn a_view_of_a_profile_that_does_not_read_leaves_a_deny_in_force() {
        use crate::permission::{
            ConfiguredRule, PermissionSession, PolicyDecision, ProposedAction, ReadPlan,
            RuleAction, RuleSet,
        };
        let (home, _workspace, mut shell) = allowlist_shell();
        let deny = RuleSet::new(vec![ConfiguredRule::new(
            "read",
            "secrets/*",
            RuleAction::Deny,
        )]);
        shell.work.rules().replace(deny.clone());
        let session = PermissionSession::new(crate::permission::PermissionMode::Ask)
            .with_live_rules(shell.work.rules().clone());
        let read = ReadPlan::new(
            "read_file",
            std::path::PathBuf::from("/w/secrets/key"),
            "secrets/key".to_string(),
            b"secrets/key".to_vec(),
            "secrets/key".to_string(),
            Vec::new(),
        );
        let denied = |session: &PermissionSession| {
            matches!(
                session.evaluate(ProposedAction::Read(&read)),
                PolicyDecision::Deny { .. }
            )
        };
        assert!(denied(&session), "the deny decides before the view");
        let settings = home.path().join(".xfx").join("settings.json");
        std::fs::create_dir_all(settings.parent().unwrap()).unwrap();
        std::fs::write(&settings, "{\"permission\": {\"bash\": \"perhaps\"}}").unwrap();
        shell.route_bytes(b"/allowlist\r");
        assert_eq!(*shell.work.rules().current(), deny);
        assert!(denied(&session), "the deny still decides after the view");
        let document = shell.document();
        assert_eq!(
            [document[0].as_str(), document[1].trim_start()].join(" "),
            "\u{2717} settings: Failed to load settings: user config diagnostic: invalid_value key=permission `perhaps` is not a permission action; use allow, ask or deny; the permission rules in force are unchanged",
            "{document:?}"
        );
    }

    #[test]
    fn a_launch_says_what_the_configuration_could_not_use_as_upstream_does() {
        // `writeCollapsedStartupNotice` (`app_bootstrap_runtime.zig:267-272`,
        // `:666-687`): one neutral line in the document, the diagnostics on
        // the full transcript only -- and here, since the table did not read,
        // the refusal of every tool and the way back.
        let home = tempfile::tempdir().expect("a home");
        let workspace = tempfile::tempdir().expect("a workspace");
        let settings = home.path().join(".xfx").join("settings.json");
        std::fs::create_dir_all(settings.parent().unwrap()).unwrap();
        std::fs::write(&settings, r#"{"permission":{"bash":"sure"}}"#).unwrap();
        let broken = config(home.path(), workspace.path());
        let (work, sent, control, _changes) = WorkHandle::detached_with_changes();
        let mut shell = Fixture {
            shell: Shell::new(
                &broken,
                crate::tui::layout::solve(40, 120, 1).expect("a band"),
                PALETTE,
                false,
                work,
            )
            .anchored(),
            sent,
            control,
        };
        shell.config_issues(&broken);
        // The diagnostics are the full transcript's, not the document's.
        assert_eq!(
            shell.document(),
            [
                "* config: 1 configuration issue (ctrl+o to view)",
                "",
                "! permissions: every tool is refused: a permission table did not read (user config diagnostic: invalid_value",
                "  key=permission `sure` is not a permission action; use allow, ask or deny); fix it, then /allowlist reads it again",
                "",
            ]
        );
        shell.route_bytes(b"\x0f");
        let screen = full_screen(&shell);
        assert!(
            screen.iter().any(|row| row
                == "* config: user: invalid_value; key=permission; `sure` is not a permission action; use allow, ask or deny"),
            "{screen:#?}"
        );
        // In full access, which consults no table, it says the table is not
        // applied rather than that every tool is refused.
        std::fs::write(
            &settings,
            r#"{"permission_mode":"yolo","permission":{"bash":"sure"}}"#,
        )
        .unwrap();
        let yolo = config(home.path(), workspace.path());
        assert_eq!(yolo.permission_mode, PermissionMode::Yolo);
        let (work, sent, control, _changes) = WorkHandle::detached_with_changes();
        let mut full_access = Fixture {
            shell: Shell::new(
                &yolo,
                crate::tui::layout::solve(40, 120, 1).expect("a band"),
                PALETTE,
                false,
                work,
            )
            .anchored(),
            sent,
            control,
        };
        full_access.config_issues(&yolo);
        let said = full_access.document().join(" ");
        let said = said.split_whitespace().collect::<Vec<_>>().join(" ");
        assert!(
            said.contains(
                "! permissions: full access consults no table, so it is not applied; every other mode refuses every tool: a permission table did not read"
            ),
            "{said}"
        );
        assert!(!said.contains("every tool is refused"), "{said}");
        // A configuration with nothing to say says nothing.
        let (home, workspace, mut quiet) = allowlist_shell();
        let clean = config(home.path(), workspace.path());
        quiet.config_issues(&clean);
        assert!(quiet.document().is_empty(), "{:?}", quiet.document());
    }

    /// `row` with every SGR sequence taken out: what a confirmation's rows
    /// say, whatever they are painted in.
    fn sgr_free(row: &str) -> String {
        let mut out = String::with_capacity(row.len());
        let mut rest = row;
        while let Some(at) = rest.find("\u{1b}[") {
            out.push_str(&rest[..at]);
            let after = &rest[at + 2..];
            match after.find('m') {
                Some(end) => rest = &after[end + 1..],
                None => {
                    rest = "";
                }
            }
        }
        out.push_str(rest);
        out
    }

    /// A shell whose runtime has published a saved session's rule store, in
    /// a workspace the test keeps.
    fn remembering_shell() -> (
        tempfile::TempDir,
        tempfile::TempDir,
        std::path::PathBuf,
        Fixture,
    ) {
        let (home, workspace, shell) = allowlist_shell();
        let session = home.path().join("session");
        std::fs::create_dir_all(&session).expect("a session directory");
        let rules = crate::permission::session_rules::path_in(&session);
        shell.work.publish_saved_rules(rules.clone());
        (home, workspace, rules, shell)
    }

    /// Every file under `root`, however deep.
    fn files_under(root: &std::path::Path) -> Vec<std::path::PathBuf> {
        let mut found = Vec::new();
        let mut pending = vec![root.to_path_buf()];
        while let Some(dir) = pending.pop() {
            for entry in std::fs::read_dir(&dir).expect("a directory").flatten() {
                let path = entry.path();
                if path.is_dir() {
                    pending.push(path);
                } else {
                    found.push(path);
                }
            }
        }
        found
    }

    /// The confirmation band's rows, uncoloured.
    fn confirmation_rows(shell: &Fixture) -> Vec<String> {
        shell.band_rows().iter().map(|row| sgr_free(row)).collect()
    }

    #[test]
    fn a_rule_remembered_before_the_first_prompt_is_held_and_written_nowhere_yet() {
        // fx's session is open from launch: a `remember` typed before the
        // first prompt opens its confirmation (`handlePermissionRuleManagement`,
        // `src/core/app/app_commands.zig:598-750@481104fd`), and Enter puts the
        // rule in the session's state at once (`input_approval_runtime.zig:
        // 277-297`) and in the lines it holds until its first turn
        // (`src/core/session_manager/session.zig:415-429`). Red before: xfx
        // refused it, `require an active saved session`.
        let (home, workspace, mut shell) = allowlist_shell();
        shell.route_bytes(
            b"/permissions remember deny write_file {\"path\":\"b.txt\",\"content\":\"y\"}\r",
        );
        assert!(shell.rule_confirm.is_some(), "{:?}", shell.document());
        let band = confirmation_rows(&shell);
        assert!(
            band.contains(&"  Remember deny for this saved session?".to_string()),
            "{band:?}"
        );
        assert!(
            band.contains(
                &"  $ write_file b.txt preimage=absent after=a1fce4363854ff88".to_string()
            ),
            "{band:?}"
        );
        shell.route_bytes(b"\r");
        assert_eq!(
            shell.document(),
            vec![
                "* permissions: saved-session permission rule updated".to_string(),
                String::new(),
            ]
        );
        // Held: nothing reaches the disk before the session's first save.
        for root in [home.path(), workspace.path()] {
            let written: Vec<_> = files_under(root)
                .into_iter()
                .filter(|path| {
                    path.file_name()
                        .is_some_and(|name| name == "permissions.json" || name == "b.txt")
                })
                .collect();
            assert!(written.is_empty(), "{written:?}");
        }
        // And listed as the session's, through the panel's rows, as fx lists
        // it (`cap/…/fx-p5-panels-permissions-40x120-saved`).
        shell.route_bytes(b"/permissions\r");
        let band = confirmation_rows(&shell);
        assert!(
            band.contains(&format!("  Saved rules{}1", " ".repeat(9))),
            "{band:?}"
        );
        assert!(
            band.contains(&format!(
                "{}\u{2022} 1 deny write_file b.txt preimage=absent after=a1fce4363854ff88",
                " ".repeat(22)
            )),
            "{band:?}"
        );
    }

    #[test]
    fn a_rule_revoked_before_the_first_prompt_is_gone_and_its_id_is_never_reused() {
        // fx's revoke takes the rule out of the state it holds, spending a
        // generation (`applyRevoke`, `session_permission_state.zig`), so the
        // rule does not come back and its id is not handed out again. Red
        // before: neither form was taken before the first prompt.
        let (_home, _workspace, mut shell) = allowlist_shell();
        shell.route_bytes(
            b"/permissions remember allow write_file {\"path\":\"a.txt\",\"content\":\"x\"}\r",
        );
        assert!(shell.rule_confirm.is_some(), "{:?}", shell.document());
        shell.route_bytes(b"\r");
        shell.route_bytes(
            b"/permissions remember deny write_file {\"path\":\"b.txt\",\"content\":\"y\"}\r",
        );
        shell.route_bytes(b"\r");
        shell.route_bytes(b"/permissions revoke 1\r");
        let band = confirmation_rows(&shell);
        assert!(
            band.contains(&"  Revoke this saved-session permission rule?".to_string()),
            "{band:?}"
        );
        assert!(
            band.contains(
                &"  $ write_file a.txt preimage=absent after=2d711642b726b044".to_string()
            ),
            "{band:?}"
        );
        shell.route_bytes(b"1");
        assert_eq!(
            shell.document(),
            vec![
                "* permissions: saved-session permission rule updated".to_string(),
                String::new(),
                "* permissions: saved-session permission rule updated".to_string(),
                String::new(),
                "* permissions: saved-session permission rule updated".to_string(),
                String::new(),
            ]
        );
        shell.route_bytes(b"/permissions revoke 1\r");
        assert_eq!(
            shell.document(),
            vec![
                "! permissions: saved-session permission rule not found".to_string(),
                String::new(),
            ],
            "the revoked rule came back"
        );
        // Remembered again, it is a new rule with a new id.
        shell.route_bytes(
            b"/permissions remember allow write_file {\"path\":\"a.txt\",\"content\":\"x\"}\r",
        );
        shell.route_bytes(b"\r");
        shell.route_bytes(b"/permissions\r");
        let band = confirmation_rows(&shell);
        assert!(
            band.contains(&format!("  Saved rules{}2", " ".repeat(9))),
            "{band:?}"
        );
        for item in [
            "2 deny write_file b.txt preimage=absent after=a1fce4363854ff88",
            "4 allow write_file a.txt preimage=absent after=2d711642b726b044",
        ] {
            assert!(
                band.contains(&format!("{}\u{2022} {item}", " ".repeat(22))),
                "{item}: {band:?}"
            );
        }
    }

    #[test]
    fn a_new_session_before_the_first_prompt_forgets_the_rules_held_for_the_last() {
        // fx's `/new` resets the session's state before it starts the next one
        // (`SessionRuntime.reset` -> `clearPermissionState`,
        // `src/core/session/session.zig:1430-1437`, from
        // `applyIdleLiveSessionTransition`, `app_session_runtime.zig:1816@481104fd`):
        // what was held for the session left is not the next one's.
        let (_home, _workspace, mut shell) = allowlist_shell();
        shell.route_bytes(
            b"/permissions remember deny write_file {\"path\":\"b.txt\",\"content\":\"y\"}\r",
        );
        assert!(shell.rule_confirm.is_some(), "{:?}", shell.document());
        shell.route_bytes(b"\r");
        shell.route_bytes(b"/new\r");
        let _ = shell.document();
        // Until the runtime's fence, the session is still changing
        // (`a_rule_typed_while_a_new_session_waits_for_the_last_to_unwind_is_refused`).
        shell.apply(UiEvent::Fresh { through: 0 });
        shell.route_bytes(b"/permissions revoke 1\r");
        assert_eq!(
            shell.document(),
            vec![
                "! permissions: saved-session permission rule not found".to_string(),
                String::new(),
            ]
        );
    }

    /// The refusal a `remember` or `revoke` gets while the session is
    /// changing under it, as the document says it.
    const CHANGING: &str = "! permissions: wait for the session to finish changing before managing saved-session rules";

    #[test]
    fn a_rule_typed_while_a_new_session_waits_for_the_last_to_unwind_is_refused() {
        // Review PERM-EARLY-b, item 1. `/new` from an open session: until the
        // runtime's fence for the reset arrives (`UiEvent::Fresh`), the store
        // this shell holds is still the session being left's, and nothing is
        // held to forget. A rule confirmed then would go into the left
        // session's file under "updated", and the new session would never
        // have it. Refused, saying why, until the fence; then the next
        // session's. Red before: the confirmation opened and wrote the old file.
        let (_home, _workspace, rules, mut shell) = remembering_shell();
        shell.route_bytes(b"/new\r");
        let _ = shell.document();
        shell.route_bytes(
            b"/permissions remember deny write_file {\"path\":\"b.txt\",\"content\":\"y\"}\r",
        );
        shell.route_bytes(b"\r");
        assert!(
            !rules.exists(),
            "a rule confirmed while the reset drained went into the left session"
        );
        shell.route_bytes(b"/permissions revoke 1\r");
        assert!(shell.rule_confirm.is_none(), "a confirmation opened");
        assert_eq!(
            shell.document(),
            vec![
                CHANGING.to_string(),
                String::new(),
                CHANGING.to_string(),
                String::new(),
            ]
        );
        // The fence, and the next session's store as the runtime publishes it.
        let next = rules.with_file_name("next").join("permissions.json");
        shell.work.saved_rules().publish_pending(next.clone());
        shell.apply(UiEvent::Fresh { through: 0 });
        shell.route_bytes(
            b"/permissions remember deny write_file {\"path\":\"b.txt\",\"content\":\"y\"}\r",
        );
        assert!(shell.rule_confirm.is_some(), "{:?}", shell.document());
        shell.route_bytes(b"\r");
        assert_eq!(
            shell.document(),
            vec![
                "* permissions: saved-session permission rule updated".to_string(),
                String::new(),
            ]
        );
        assert!(!rules.exists());
        assert_eq!(
            shell
                .work
                .saved_rules()
                .view()
                .state
                .expect("held")
                .rules
                .len(),
            1
        );
    }

    #[test]
    fn a_rule_typed_while_a_resume_is_on_its_way_is_refused() {
        // Review PERM-EARLY-b, item 2. The picker's Enter hands the runtime a
        // resume, and Escape can take the picker down before it is made. A
        // rule confirmed then would be held, said "updated", and dropped when
        // the resumed session's store is published. Refused, saying why,
        // until the runtime has got past the switch. Red before: the
        // confirmation opened and said "updated".
        let (_home, _workspace, mut shell) = allowlist_shell();
        shell
            .work
            .submit_switch(TurnWork::Resume("1793786870949-17cfc234b1a39f46".into()))
            .expect("queued");
        shell.route_bytes(
            b"/permissions remember deny write_file {\"path\":\"b.txt\",\"content\":\"y\"}\r",
        );
        shell.route_bytes(b"\r");
        assert!(shell.rule_confirm.is_none(), "a confirmation opened");
        assert_eq!(shell.document(), vec![CHANGING.to_string(), String::new()]);
        assert_eq!(
            shell.work.saved_rules().view().state.expect("held"),
            crate::permission::session_rules::State::default(),
            "a rule was held for a session the resume replaces"
        );
        // The runtime has made it.
        let _ = shell.work.title_desk().worked_through(1);
        shell.route_bytes(
            b"/permissions remember deny write_file {\"path\":\"b.txt\",\"content\":\"y\"}\r",
        );
        assert!(shell.rule_confirm.is_some(), "{:?}", shell.document());
        // A switch handed over while that confirmation is up: its Enter is
        // made nowhere, and says why.
        shell
            .work
            .submit_switch(TurnWork::Resume("1793786870949-17cfc234b1a39f46".into()))
            .expect("queued");
        shell.route_bytes(b"\r");
        assert!(shell.rule_confirm.is_none());
        assert_eq!(shell.document(), vec![CHANGING.to_string(), String::new()]);
        assert_eq!(
            shell.work.saved_rules().view().state.expect("held"),
            crate::permission::session_rules::State::default()
        );
    }

    #[test]
    fn a_confirmation_held_across_the_first_save_lands_in_the_file_it_was_for() {
        // The runtime writes what is held into the session it opens and lets
        // go of it under the store's one lock (`Runtime::open_next`): a
        // `remember` shown while held and confirmed once the session is open
        // is made in the session's file, against the generations the held
        // rules carried there; one shown for a store that is no longer this
        // shell's -- a resume took another session -- is made nowhere.
        use crate::permission::session_rules;
        let (home, _workspace, mut shell) = allowlist_shell();
        let session = home.path().join("next");
        let rules = session_rules::path_in(&session);
        shell.work.saved_rules().publish_pending(rules.clone());
        shell.route_bytes(
            b"/permissions remember allow write_file {\"path\":\"a.txt\",\"content\":\"x\"}\r",
        );
        shell.route_bytes(b"\r");
        shell.route_bytes(
            b"/permissions remember deny write_file {\"path\":\"b.txt\",\"content\":\"y\"}\r",
        );
        assert!(shell.rule_confirm.is_some());
        // The first save, as the runtime makes it.
        {
            let mut slot = shell.work.saved_rules().lock();
            let held = slot.first_save(&rules).expect("a rule is held");
            std::fs::create_dir(&session).expect("the session's directory");
            session_rules::seed(&session, &held).expect("written");
            slot.opened(rules.clone());
        }
        shell.route_bytes(b"\r");
        assert_eq!(
            shell.document().iter().rev().nth(1).map(String::as_str),
            Some("* permissions: saved-session permission rule updated")
        );
        let state = session_rules::load(&rules).expect("the store");
        let shown: Vec<(u64, &str)> = state
            .rules
            .iter()
            .map(|rule| (rule.id, rule.decision.label()))
            .collect();
        assert_eq!(shown, vec![(1, "allow"), (2, "deny")]);

        // Another session's store now: a confirmation shown for this one is
        // refused, and neither file moves.
        shell.route_bytes(b"/permissions revoke 1\r");
        assert!(shell.rule_confirm.is_some());
        let other = home.path().join("other");
        std::fs::create_dir(&other).expect("another session");
        shell
            .work
            .publish_saved_rules(session_rules::path_in(&other));
        shell.route_bytes(b"1");
        assert_eq!(
            shell.document().iter().rev().nth(1).map(String::as_str),
            Some("! permissions: saved-session permission rule changed before confirmation")
        );
        assert_eq!(session_rules::load(&rules).expect("the store"), state);
        assert!(!session_rules::path_in(&other).exists());
    }

    #[test]
    fn remember_opens_upstreams_confirmation_and_enter_keeps_the_rule() {
        let (_home, workspace, rules, mut shell) = remembering_shell();
        shell.route_bytes(
            b"/permissions remember allow write_file {\"path\":\"a.txt\",\"content\":\"x\"}\r",
        );
        let band: Vec<String> = shell.band_rows().iter().map(|row| sgr_free(row)).collect();
        let at = band
            .iter()
            .position(|row| row.contains("Permission needed · Choose one"))
            .expect("the confirmation is up");
        assert!(band[at].ends_with("Permission rule"), "{band:?}");
        assert_eq!(band[at + 2], "  Remember allow for this saved session?");
        assert_eq!(
            band[at + 3],
            "  Confirm this exact saved-session permission rule. The action will not run."
        );
        // `sha256("x")`'s first eight bytes, as upstream shows them.
        assert_eq!(
            band[at + 4],
            "  $ write_file a.txt preimage=absent after=2d711642b726b044"
        );
        assert_eq!(band[at + 6], "  ❯ 1. Confirm");
        assert_eq!(band[at + 7], "    2. Cancel");
        assert_eq!(
            sgr_free(shell.band_rows().last().expect("a hint row")),
            "1–2 choose    enter confirm    esc cancel"
        );
        assert!(
            !workspace.path().join("a.txt").exists(),
            "the action did not run"
        );
        shell.route_bytes(b"\r");
        assert!(shell.rule_confirm.is_none());
        assert_eq!(
            shell.document(),
            vec![
                "* permissions: saved-session permission rule updated".to_string(),
                String::new(),
            ]
        );
        let state = crate::permission::session_rules::load(&rules).expect("the store");
        assert_eq!(state.rules.len(), 1);
        assert_eq!(
            state.rules[0].display,
            "write_file a.txt preimage=absent after=2d711642b726b044"
        );
        // Listed in the bare command's panel
        // (`cap/panels/new/fx-p5-panels-permissions-40x120-saved`), and
        // revoked through the same band.
        shell.route_bytes(b"/permissions\r");
        assert_eq!(panel_value(&shell, "Saved rules").as_deref(), Some("1"));
        assert!(
            uncoloured_rows(&shell.band_rows()).contains(&permissions_item(
                "1 allow write_file a.txt preimage=absent after=2d711642b726b044"
            )),
            "{:?}",
            uncoloured_rows(&shell.band_rows())
        );
        escape(&mut shell);
        shell.route_bytes(b"/permissions revoke 1\r");
        let band: Vec<String> = shell.band_rows().iter().map(|row| sgr_free(row)).collect();
        assert!(band.contains(&"  Revoke this saved-session permission rule?".to_string()));
        assert!(band.contains(
            &"  Confirm revocation of this stored rule. No current action will be prepared or run."
                .to_string()
        ));
        shell.route_bytes(b"1");
        assert!(crate::permission::session_rules::load(&rules)
            .expect("the store")
            .rules
            .is_empty());
        assert_eq!(
            shell.document().iter().rev().nth(1).map(String::as_str),
            Some("* permissions: saved-session permission rule updated")
        );
    }

    #[test]
    fn a_change_in_an_added_root_can_be_remembered_as_one_in_the_workspace_can() {
        // Upstream prepares a rule under the session's own scope, added roots
        // and all (`.access_scope = input.access_scope`,
        // `tool_admission.zig:2270-2289`), so a write the session may make in
        // an added directory is a write it may remember -- and, like any
        // other, it does not run.
        let (_home, _workspace, _rules, mut shell) = remembering_shell();
        let added = tempfile::tempdir().expect("an added directory");
        let added = added.path().canonicalize().expect("canonical");
        shell.workspace_access = WorkspaceAccess::load(
            &shell.workspace.clone(),
            &[added.to_string_lossy().into_owned()],
        );
        let target = added.join("plan.md");
        let line = format!(
            "/permissions remember allow write_file {{\"path\":\"{}\",\"content\":\"x\"}}\r",
            target.display()
        );
        shell.route_bytes(line.as_bytes());
        assert!(
            shell.rule_confirm.is_some(),
            "not prepared: {:?}",
            shell.document()
        );
        let band: Vec<String> = shell.band_rows().iter().map(|row| sgr_free(row)).collect();
        assert!(
            band.iter().any(|row| row.contains(&format!(
                "$ write_file {} preimage=absent",
                target.display()
            ))),
            "{band:?}"
        );
        assert!(!target.exists(), "the action ran");
        // A directory that is not one of the session's is still refused.
        shell.route_bytes(&[0x1b]);
        shell.settle_input(Instant::now() + Decoder::ESC_TIMEOUT);
        let outside = tempfile::tempdir().expect("elsewhere");
        let line = format!(
            "/permissions remember allow write_file {{\"path\":\"{}\",\"content\":\"x\"}}\r",
            outside
                .path()
                .canonicalize()
                .unwrap()
                .join("x.md")
                .display()
        );
        let _ = shell.document();
        shell.route_bytes(line.as_bytes());
        assert!(shell.rule_confirm.is_none());
        assert_eq!(
            shell.document().first().map(String::as_str),
            Some("✗ permissions: could not prepare that exact permission action without executing it")
        );
    }

    #[test]
    fn escape_closes_the_confirmation_silently_and_two_says_cancelled() {
        let (_home, _workspace, rules, mut shell) = remembering_shell();
        shell.route_bytes(b"/permissions remember deny create_folder {\"path\":\"d\"}\r");
        assert!(shell.rule_confirm.is_some());
        shell.route_bytes(&[0x1b]);
        shell.settle_input(Instant::now() + Decoder::ESC_TIMEOUT);
        assert!(shell.rule_confirm.is_none(), "Escape closes it");
        assert!(shell.document().is_empty(), "{:?}", shell.document());
        shell.route_bytes(b"/permissions remember deny create_folder {\"path\":\"d\"}\r");
        shell.route_bytes(b"2");
        assert_eq!(
            shell.document(),
            vec![
                "* permissions: saved-session permission change cancelled".to_string(),
                String::new(),
            ]
        );
        assert!(!rules.exists(), "nothing was kept");
    }

    #[test]
    fn a_remember_that_cannot_be_prepared_or_a_revoke_of_nothing_says_why() {
        let (_home, _workspace, _rules, mut shell) = remembering_shell();
        for line in [
            &b"/permissions remember allow bash {\"command\":\"ls\"}\r"[..],
            b"/permissions remember allow write_file not-json\r",
            b"/permissions remember allow read_file {\"path\":\"a\"}\r",
        ] {
            shell.route_bytes(line);
        }
        shell.route_bytes(b"/permissions revoke 99\r");
        shell.route_bytes(b"/permissions revoke abc\r");
        let prepared =
            "✗ permissions: could not prepare that exact permission action without executing it";
        assert_eq!(
            shell.document(),
            vec![
                prepared.to_string(),
                String::new(),
                prepared.to_string(),
                String::new(),
                prepared.to_string(),
                String::new(),
                "! permissions: saved-session permission rule not found".to_string(),
                String::new(),
                "✗ usage: /permissions remember <allow|deny> <tool-name> <arguments-json>"
                    .to_string(),
                "         /permissions revoke <rule-id>".to_string(),
                String::new(),
            ]
        );
    }

