    #[test]
    fn a_typed_path_is_attached_as_the_prompt_is_sent() {
        // `tui-composer-edit-contracts.test.ts:1018-1030`: `inspect i.png,`
        // sends `inspect [Image #1],` and one file.
        let mut shell = attaching();
        shell.route_bytes(b"inspect shot.png,\r");
        assert_eq!(
            sent_with_images(&mut shell),
            ("inspect [Image #1],".to_string(), vec![1])
        );
        assert_eq!(
            shell.document(),
            card(&format!("inspect {},", linked_shot(&shell, 1)))
        );
        shell.work.finished_one();
        // The picker's spelling, quoted, and the next number. Put in whole:
        // typed, the `@` would open the picker and the Return be its.
        shell
            .editor
            .set_text("@\"shot.png\" and @shot.png", Entities::new());
        shell.route_bytes(b"\r");
        assert_eq!(
            sent_with_images(&mut shell),
            ("[Image #2] and [Image #3]".to_string(), vec![2, 3])
        );
        shell.work.finished_one();
        // A badge already in the draft keeps its number and goes first in
        // the order the draft holds them.
        shell.route_bytes(b"/image shot.png\r");
        shell.document();
        shell.route_bytes(b" vs shot.png\r");
        assert_eq!(
            sent_with_images(&mut shell),
            ("[Image #4] vs [Image #5]".to_string(), vec![4, 5])
        );
    }

    #[test]
    fn a_typed_path_that_cannot_be_attached_stops_the_prompt_or_is_left_as_words() {
        // `input_submit_runtime.zig:756-776`: missing, unsupported, a
        // directory -- words; too large -- said, nothing sent, the draft kept.
        let mut shell = attaching();
        std::fs::create_dir(shell.workspace.join("pics.png")).expect("a directory");
        shell.route_bytes(b"read nope.png notes.png pics.png\r");
        assert_eq!(
            sent_with_images(&mut shell),
            ("read nope.png notes.png pics.png".to_string(), Vec::new())
        );
        shell.document();
        shell.route_bytes(b"and huge.png\r");
        assert_eq!(
            shell.document(),
            said(notice::Notice::error(
                "images",
                "image exceeds the 20 MiB limit"
            ))
        );
        assert!(shell.sent.try_recv().is_err(), "the prompt was sent");
        assert_eq!(shell.editor.text(), "and huge.png");
        // Nothing was recorded for the line that did not go.
        shell.route_bytes(b"\x15\x1b[A");
        assert_eq!(shell.editor.text(), "read nope.png notes.png pics.png");
    }

    #[test]
    fn a_badge_whose_number_the_prompt_types_in_words_is_sent_under_a_fresh_one() {
        // `tui-composer-edit-contracts.test.ts:1033-1047` and
        // `fx-image-composer-40x120-lookalike-sent`: the words stay `[Image
        // #1]`, the badge is sent as #2, and #2 is spent.
        let mut shell = attaching();
        pasted(&mut shell, "shot.png");
        shell.route_bytes(b" duplicate [Image #1]\r");
        assert_eq!(
            sent_with_images(&mut shell),
            ("[Image #2] duplicate [Image #1]".to_string(), vec![2])
        );
        // The badge is linked to its file; the words are not a badge.
        assert_eq!(
            shell.document(),
            card(&format!("{} duplicate [Image #1]", linked_shot(&shell, 2)))
        );
        shell.work.finished_one();
        // The next number skips every one the words or another badge say.
        pasted(&mut shell, "shot.png shot.png");
        assert_eq!(attached_ids(&shell), [3, 4]);
        shell.route_bytes(b" [Image #3] [Image #5]\r");
        assert_eq!(
            sent_with_images(&mut shell),
            (
                "[Image #6] [Image #4] [Image #3] [Image #5]".to_string(),
                vec![6, 4]
            )
        );
        shell.work.finished_one();
        shell.route_bytes(b"/image shot.png\r");
        assert_eq!(attached_ids(&shell), [7]);
    }

    #[test]
    fn a_renumbered_prompt_the_runtime_refuses_keeps_its_badge_and_spends_nothing() {
        let mut shell = attaching();
        shell.route_bytes(b"first\r");
        shell.route_bytes(b"second\r");
        shell.document();
        pasted(&mut shell, "shot.png");
        shell.route_bytes(b" [Image #1]\r");
        assert!(shell.hint().contains(QUEUE_REJECTED), "{}", shell.hint());
        assert_eq!(shell.editor.text(), "[Image 1] [Image #1]");
        assert_eq!(attached_ids(&shell), [1]);
        assert_eq!(shell.images_next, 2);
    }

    #[test]
    fn a_prompt_the_runtime_refuses_keeps_the_paths_that_were_typed() {
        // Upstream attaches a typed path only once the prompt is admitted
        // (`commitStableExtractedImageIds`, `input_submit_runtime.zig:872-873`):
        // a full queue leaves the draft as typed and spends no number.
        let mut shell = attaching();
        shell.route_bytes(b"first\r");
        shell.route_bytes(b"second\r");
        shell.document();
        shell.route_bytes(b"look at shot.png\r");
        assert!(shell.hint().contains(QUEUE_REJECTED), "{}", shell.hint());
        assert_eq!(shell.editor.text(), "look at shot.png");
        assert!(attached_ids(&shell).is_empty());
        // And it was not sent, so it is not walked back to: the newest line
        // is the last one the runtime took.
        shell.route_bytes(b"\x15\x1b[A");
        assert_eq!(shell.editor.text(), "second");
        shell.route_bytes(b"\x15");
        shell.route_bytes(b"look at shot.png");
        assert_eq!(shell.picks_up(), TurnWork::Submit("first".to_string()));
        assert_eq!(shell.picks_up(), TurnWork::Submit("second".to_string()));
        shell.work.finished_one();
        shell.route_bytes(b"\r");
        assert_eq!(
            sent_with_images(&mut shell),
            ("look at [Image #1]".to_string(), vec![1])
        );
    }

    #[test]
    fn ctrl_v_puts_the_clipboard_image_at_the_caret_with_no_notice() {
        // `image_commands.zig:86-104`: a badge and a repaint, no notice -- and
        // the image is named by the copy the session will keep of it.
        let tool = crate::clipboard::fake::FakeTool::holding(Some(crate::image::fixture::SHOT_PNG));
        let mut shell = attaching();
        shell.clipboard_reads = ClipboardReads::new(tool.clipboard());
        shell.route_bytes(b"look ");
        shell.route_bytes(b"\x16");
        let written = read_settled(&mut shell);
        assert!(
            written.is_empty(),
            "a pasted image wrote a notice: {written:?}"
        );
        assert_eq!(shell.editor.text(), "look [Image 1]");
        let name =
            crate::image::snapshot_name(1, &crate::image::digest(crate::image::fixture::SHOT_PNG));
        shell.route_bytes(b" /images\r");
        // `look ` is not a badge, so this is a prompt, not the command.
        assert!(matches!(shell.picks_up(), TurnWork::Attached { .. }));
        shell.document();
        // `/paste` is the same read.
        shell.route_bytes(b"/paste\r");
        assert!(read_settled(&mut shell).is_empty());
        shell.route_bytes(b" /images\r");
        assert_eq!(
            shell.document(),
            [
                "* images: 1 pending".to_string(),
                format!("   - {} (image/png)", name.replace("image-1-", "image-2-")),
                String::new()
            ]
        );
    }

    #[test]
    fn a_clipboard_image_is_copied_at_the_paste_and_its_badge_links_the_copy() {
        // `insertImageAtCursor` (`image_commands.zig:140-148@481104fd`) and
        // `fx-image-paste-40x120-paste.ansi`: the badge links the copy written
        // at the paste, in the composer and on the card.
        let tool = crate::clipboard::fake::FakeTool::holding(Some(crate::image::fixture::SHOT_PNG));
        let mut shell = attaching();
        shell.clipboard_reads = ClipboardReads::new(tool.clipboard());
        shell.route_bytes(b"\x16");
        assert!(read_settled(&mut shell).is_empty());
        let image = shell
            .editor
            .entities()
            .images()
            .next()
            .cloned()
            .expect("an image");
        assert!(image.copied && image.path.is_absolute(), "{:?}", image.path);
        assert_eq!(
            image.path.file_name().and_then(|name| name.to_str()),
            Some(image.snapshot_name().as_str())
        );
        assert_eq!(
            std::fs::read(&image.path).expect("the copy"),
            crate::image::fixture::SHOT_PNG
        );
        {
            use std::os::unix::fs::PermissionsExt;
            let mode = |path: &std::path::Path| {
                std::fs::metadata(path).expect("mode").permissions().mode() & 0o777
            };
            assert_eq!(mode(&image.path), 0o600);
            assert_eq!(mode(image.path.parent().expect("a directory")), 0o700);
        }
        let open = super::super::hyperlink::open(
            "",
            &super::super::hyperlink::file_uri(&image.path).expect("a link"),
        );
        let composer = shell.editor.painted_rows(118, "", "").join("");
        assert!(
            composer.contains(&format!("{open}[Image 1]")),
            "{composer:?}"
        );
        shell.route_bytes(b" what is this?\r");
        let _ = shell.picks_up();
        let card = shell.document().join("");
        assert!(card.contains(&format!("{open}[Image 1]")), "{card:?}");
        // The copy is the session's to remove: gone when the shell is.
        let dir = shell.paste_copies.dir().expect("a directory").to_path_buf();
        drop(shell);
        assert!(!dir.exists(), "{dir:?} outlived the session");
    }

    #[test]
    fn an_unsaved_sessions_attached_file_gets_a_private_temporary_copy() {
        // Upstream captures every attachment into its process's temporary
        // folder (`captureImageAttachment`, `app_session_runtime.zig:1332-1345`,
        // `createTempSnapshotDir`, `image_attachments.zig:248-275@481104fd`),
        // and an unsaved session's note names that copy. xfx's goes where a
        // paste's does: owner-only, in the shell's private directory, gone
        // with the shell. The file the user named is left as it was.
        let workspace = tempfile::tempdir().expect("a workspace");
        let source = workspace.path().join("shot.png");
        std::fs::write(&source, crate::image::fixture::SHOT_PNG).expect("a picture");
        let config = RuntimeConfig::load_with(
            &Environment::new(
                Some(std::path::PathBuf::from("relative/home")),
                BTreeMap::new(),
            ),
            workspace.path(),
        )
        .expect("load a configuration");
        let (work, _sent, _control) = WorkHandle::detached();
        let mut shell = Shell::new(
            &config,
            crate::tui::layout::solve(40, 120, 1).expect("a band"),
            PALETTE,
            false,
            work,
        );
        assert!(shell.unsaved);
        shell.workspace = workspace.path().canonicalize().expect("canonical");
        shell.route_bytes(b"/image shot.png\r");
        let image = shell
            .editor
            .entities()
            .images()
            .next()
            .cloned()
            .expect("an image");
        assert!(!image.copied);
        assert_eq!(
            image.name(),
            "shot.png",
            "the badge and the notice keep its name"
        );
        let copy = image.copy.clone().expect("a temporary copy");
        assert_eq!(image.own_copy(), Some(copy.as_path()));
        assert_ne!(copy, image.path);
        assert_eq!(
            Some(copy.parent().expect("a directory")),
            shell.paste_copies.dir(),
            "beside the paste copies"
        );
        assert_eq!(
            copy.file_name().and_then(|name| name.to_str()),
            Some(image.snapshot_name().as_str())
        );
        assert_eq!(
            std::fs::read(&copy).expect("the copy"),
            crate::image::fixture::SHOT_PNG
        );
        {
            use std::os::unix::fs::PermissionsExt;
            let mode = |path: &std::path::Path| {
                std::fs::metadata(path).expect("mode").permissions().mode() & 0o777
            };
            assert_eq!(mode(&copy), 0o600);
            assert_eq!(mode(copy.parent().expect("a directory")), 0o700);
        }
        assert_eq!(
            std::fs::read(&source).expect("the source"),
            crate::image::fixture::SHOT_PNG
        );
        let dir = copy.parent().expect("a directory").to_path_buf();
        drop(shell);
        assert!(!dir.exists(), "{dir:?} outlived the session");

        // A session that saves keeps its own copy in the log, and makes none.
        let mut saved = attaching();
        saved.route_bytes(b"/image shot.png\r");
        let image = saved
            .editor
            .entities()
            .images()
            .next()
            .cloned()
            .expect("an image");
        assert_eq!(image.copy, None);
        assert_eq!(saved.paste_copies.dir(), None);
    }

    /// The temporary copy an unsaved session made of `image`, checked: beside
    /// the paste copies, owner-only, the bytes the image holds, and never the
    /// file it was attached from.
    fn checked_copy(shell: &Fixture, image: &crate::image::Image) -> std::path::PathBuf {
        use std::os::unix::fs::PermissionsExt;
        let copy = image
            .copy
            .clone()
            .unwrap_or_else(|| panic!("image #{} has no temporary copy", image.id));
        assert_ne!(copy, image.path, "the source is not a copy");
        assert_eq!(copy.parent(), shell.paste_copies.dir());
        assert_eq!(std::fs::read(&copy).expect("the copy"), &image.bytes[..]);
        assert_eq!(
            std::fs::metadata(&copy).expect("mode").permissions().mode() & 0o777,
            0o600
        );
        assert_eq!(image.own_copy(), Some(copy.as_path()));
        copy
    }

    // Upstream captures on each route a file is attached by: the `/image`
    // command (`insertImageAtCursor`, `src/core/images/image_commands.zig:140-143`),
    // a pasted or dropped path (`input_paste_runtime.zig:491-494`) and a path
    // typed into the prompt (`captureExtractedImages`,
    // `input_submit_runtime.zig:1219-1224@481104fd`). An unsaved session's
    // copy is made on each of them.

    /// [`attaching`], in a session that keeps no copy of its own.
    fn attaching_unsaved() -> Attaching {
        let mut shell = attaching();
        shell.unsaved = true;
        shell
    }

    #[test]
    fn an_unsaved_slash_image_makes_the_files_copy() {
        let mut shell = attaching_unsaved();
        shell.route_bytes(b"/image shot.png\r");
        let image = shell
            .editor
            .entities()
            .images()
            .next()
            .cloned()
            .expect("an image");
        checked_copy(&shell, &image);
    }

    #[test]
    fn an_unsaved_pasted_or_dropped_path_makes_the_files_copy() {
        let mut shell = attaching_unsaved();
        pasted(&mut shell, "shot.png describe this");
        let image = shell
            .editor
            .entities()
            .images()
            .next()
            .cloned()
            .expect("an image");
        checked_copy(&shell, &image);
    }

    #[test]
    fn an_unsaved_typed_path_makes_the_files_copy_as_the_prompt_is_sent() {
        let mut shell = attaching_unsaved();
        shell.route_bytes(b"inspect shot.png,\r");
        match shell.picks_up() {
            TurnWork::Attached { images, .. } => {
                assert_eq!(images.len(), 1, "{images:?}");
                checked_copy(&shell, &images[0]);
            }
            other => panic!("not a prompt with an image: {other:?}"),
        }
    }

    #[test]
    fn an_unsaved_copy_that_cannot_be_written_refuses_the_attachment_on_every_route() {
        // Upstream attaches nothing when its capture cannot write the copy:
        // the error is passed up out of the command
        // (`captureImageAttachmentForAdmission`,
        // `src/core/images/image_attachments.zig:331-347@481104fd`). The rest is
        // xfx's, in upstream's words for a file it cannot attach
        // (`image_commands.zig:39`): `/image` says why and puts no badge in,
        // a pasted path stays words, and a typed path stops the prompt with
        // the draft kept.
        let refusal = said(notice::Notice::error(
            crate::image::TOPIC,
            "failed to attach image: FileNotFound",
        ));
        let unwritable = |shell: &mut Attaching| {
            let gone = shell.workspace.join("no-such-directory");
            shell.paste_copies = super::super::clipboard_image::PasteCopies::at(gone);
        };
        let mut shell = attaching_unsaved();
        unwritable(&mut shell);
        shell.route_bytes(b"/image shot.png\r");
        assert_eq!(shell.document(), refusal);
        assert_eq!(shell.editor.text(), "");
        assert!(attached_ids(&shell).is_empty());

        let mut shell = attaching_unsaved();
        unwritable(&mut shell);
        pasted(&mut shell, "shot.png describe this");
        assert_eq!(shell.editor.text(), "shot.png describe this");
        assert!(attached_ids(&shell).is_empty());
        assert_eq!(shell.document(), refusal);

        let mut shell = attaching_unsaved();
        unwritable(&mut shell);
        shell.route_bytes(b"inspect shot.png,\r");
        assert!(shell.sent.try_recv().is_err(), "the prompt was sent");
        assert_eq!(shell.editor.text(), "inspect shot.png,");
        assert_eq!(shell.document(), refusal);
    }

    #[test]
    fn a_clipboard_image_whose_copy_cannot_be_written_puts_no_badge_in() {
        // Upstream never inserts a clipboard image without the copy it links
        // (`snapshot_path orelse return error.MissingImageSnapshot`,
        // `image_commands.zig:144-145@481104fd`), and spends no number on it.
        // The notice is xfx's, in upstream's words for a paste that failed
        // (`:92`).
        let tool = crate::clipboard::fake::FakeTool::holding(Some(crate::image::fixture::SHOT_PNG));
        for keys in [&b"/paste\r"[..], b"\x16"] {
            let mut shell = attaching();
            shell.clipboard_reads = ClipboardReads::new(tool.clipboard());
            let gone = shell.workspace.join("no-such-directory");
            shell.paste_copies = super::super::clipboard_image::PasteCopies::at(gone);
            let next = shell.images_next;
            shell.route_bytes(keys);
            assert_eq!(
                read_settled(&mut shell),
                said(notice::Notice::error(
                    "images",
                    "failed to paste clipboard image: FileNotFound"
                )),
                "{keys:?}"
            );
            assert!(
                shell.editor.is_empty(),
                "{keys:?}: {:?}",
                shell.editor.text()
            );
            assert!(attached_ids(&shell).is_empty(), "{keys:?}");
            assert_eq!(shell.images_next, next, "{keys:?} spent a number");
        }
    }

    #[test]
    fn an_unsaved_typed_path_with_no_room_for_its_badge_leaves_no_copy() {
        // The prompt goes as words, as it would in a session that saves; the
        // copy made for the image that did not fit is removed then, not at
        // exit.
        let mut shell = attaching_unsaved();
        let room = "[Image 1]".len();
        let draft = format!("{} shot.png", "x".repeat(editor::MAX_COMPOSER_BYTES - room));
        assert_eq!(draft.len(), editor::MAX_COMPOSER_BYTES);
        assert!(shell.editor.insert(&draft).is_some());
        shell.route_bytes(b"\r");
        match shell.picks_up() {
            TurnWork::Submit(text) => assert_eq!(text, draft),
            other => panic!("not the prompt as words: {other:?}"),
        }
        let left: Vec<_> = shell
            .paste_copies
            .dir()
            .map(|dir| {
                std::fs::read_dir(dir)
                    .expect("the copies' directory")
                    .map(|entry| entry.expect("an entry").path())
                    .collect()
            })
            .unwrap_or_default();
        assert!(left.is_empty(), "{left:?}");
    }

    #[test]
    fn a_clipboard_with_no_image_or_no_reader_says_so() {
        // No image: neutral. No reader: upstream's error name -- which is
        // also what the capture harness's do-nothing `osascript` produces
        // (`fx-paste-40x120-paste.ansi`).
        let empty = crate::clipboard::fake::FakeTool::holding(None);
        let mut shell = attaching();
        shell.clipboard_reads = ClipboardReads::new(empty.clipboard());
        shell.route_bytes(b"/paste\r");
        assert_eq!(
            read_settled(&mut shell),
            said(notice::Notice::neutral(
                "images",
                "no image found on clipboard"
            ))
        );
        let mut shell = attaching();
        shell.route_bytes(b"\x16");
        assert_eq!(
            read_settled(&mut shell),
            said(notice::Notice::error(
                "images",
                "failed to paste clipboard image: FileNotFound"
            ))
        );
        assert!(shell.editor.is_empty());
    }

    #[test]
    fn an_image_the_composer_has_no_room_for_is_not_attached_and_says_so() {
        // `writeInputFullNotice` (`image_commands.zig:9-19`): neutral, under
        // `images`, and nothing in the draft -- reached by a clipboard image
        // arriving at a draft the badge does not fit beside.
        let tool = crate::clipboard::fake::FakeTool::holding(Some(crate::image::fixture::SHOT_PNG));
        let mut shell = attaching();
        shell.clipboard_reads = ClipboardReads::new(tool.clipboard());
        let room = "[Image 1]".len() - 1;
        assert!(shell
            .editor
            .insert(&"x".repeat(editor::MAX_COMPOSER_BYTES - room))
            .is_some());
        let before = shell.editor.text().len();
        shell.route_bytes(b"\x16");
        assert_eq!(
            read_settled(&mut shell),
            said(notice::Notice::neutral(
                "images",
                "input is full; image not attached"
            ))
        );
        assert!(attached_ids(&shell).is_empty());
        assert_eq!(shell.editor.text().len(), before, "the draft changed");
        // The number was not spent: the next image that fits is #1.
        shell.take_draft();
        shell.route_bytes(b"/image shot.png\r");
        assert_eq!(attached_ids(&shell), [1]);
    }

    #[test]
    fn an_image_the_composer_has_no_room_for_leaves_no_copy_on_any_route() {
        // Upstream discards an attachment it does not insert, its snapshot
        // with it (`image_commands.zig:114@481104fd`): no copy outlives an
        // image that was not attached. A clipboard image and `/image` ask for
        // room before any copy is made (the test after this one); a pasted
        // path is copied first, as upstream's paste captures first, and so is
        // whatever reaches `attach` with a copy -- those copies are removed
        // when the badge does not go in.
        fn copies(shell: &Attaching) -> Vec<std::path::PathBuf> {
            shell
                .paste_copies
                .dir()
                .map(|dir| {
                    std::fs::read_dir(dir)
                        .expect("the copies' directory")
                        .map(|entry| entry.expect("an entry").path())
                        .collect()
                })
                .unwrap_or_default()
        }
        fn fill(shell: &mut Attaching, room: usize) {
            assert!(shell
                .editor
                .insert(&"x".repeat(editor::MAX_COMPOSER_BYTES - room))
                .is_some());
        }
        // A clipboard image: no copy is made.
        let tool = crate::clipboard::fake::FakeTool::holding(Some(crate::image::fixture::SHOT_PNG));
        let mut shell = attaching();
        shell.clipboard_reads = ClipboardReads::new(tool.clipboard());
        fill(&mut shell, "[Image 1]".len() - 1);
        shell.route_bytes(b"\x16");
        assert_eq!(
            read_settled(&mut shell),
            said(notice::Notice::neutral(
                "images",
                "input is full; image not attached"
            ))
        );
        assert!(copies(&shell).is_empty(), "{:?}", copies(&shell));

        // A pasted path in an unsaved session: the paste does not fit with
        // its badge, so none of it lands.
        let mut shell = attaching_unsaved();
        fill(&mut shell, "shot.png".len());
        pasted(&mut shell, "shot.png");
        assert!(attached_ids(&shell).is_empty());
        assert!(shell.paste_copies.dir().is_some(), "no copy was made");
        assert!(copies(&shell).is_empty(), "{:?}", copies(&shell));

        // `attach` given an image whose copy was made, in an unsaved session:
        // the badge refused, the copy removed.
        let mut shell = attaching_unsaved();
        let shot = shell.workspace.join("shot.png");
        let image = shell
            .captured(crate::image::Image::new(
                1,
                shot,
                crate::image::MediaType::Png,
                std::sync::Arc::from(crate::image::fixture::SHOT_PNG.to_vec()),
            ))
            .expect("the copy");
        assert_eq!(copies(&shell).len(), 1);
        fill(&mut shell, "[Image 1]".len() - 1);
        assert!(!shell.attach(image));
        assert!(copies(&shell).is_empty(), "{:?}", copies(&shell));
    }

    #[test]
    fn with_no_room_a_clipboard_image_or_slash_image_says_so_before_any_copy() {
        // Upstream asks for room before it captures (`canInsert`,
        // `image_commands.zig:128-130@481104fd`, before `:140`): with no room
        // the answer is `input is full; image not attached`, whatever the copy
        // would have done, and no copy is made at all.
        let full = said(notice::Notice::neutral(
            "images",
            "input is full; image not attached",
        ));
        fn fill(shell: &mut Attaching) {
            let room = "[Image 1]".len() - 1;
            assert!(shell
                .editor
                .insert(&"x".repeat(editor::MAX_COMPOSER_BYTES - room))
                .is_some());
        }
        let unwritable = |shell: &mut Attaching| {
            let gone = shell.workspace.join("no-such-directory");
            shell.paste_copies = super::super::clipboard_image::PasteCopies::at(gone);
        };
        let tool = crate::clipboard::fake::FakeTool::holding(Some(crate::image::fixture::SHOT_PNG));

        // A clipboard image whose copy could not be written.
        let mut shell = attaching();
        shell.clipboard_reads = ClipboardReads::new(tool.clipboard());
        unwritable(&mut shell);
        fill(&mut shell);
        shell.route_bytes(b"\x16");
        assert_eq!(read_settled(&mut shell), full);
        assert!(attached_ids(&shell).is_empty());

        // `/image` in an unsaved session, whose copy could not be written.
        let mut shell = attaching_unsaved();
        unwritable(&mut shell);
        fill(&mut shell);
        shell.image("shot.png");
        assert_eq!(shell.document(), full);
        assert!(attached_ids(&shell).is_empty());

        // With copies that could be written, none is made on either route.
        let mut shell = attaching();
        shell.clipboard_reads = ClipboardReads::new(tool.clipboard());
        fill(&mut shell);
        shell.route_bytes(b"\x16");
        assert_eq!(read_settled(&mut shell), full);
        assert_eq!(
            shell.paste_copies.dir(),
            None,
            "the clipboard image was copied"
        );
        let mut shell = attaching_unsaved();
        fill(&mut shell);
        shell.image("shot.png");
        assert_eq!(shell.document(), full);
        assert_eq!(shell.paste_copies.dir(), None, "the file was copied");
    }

    #[test]
    fn a_resumed_session_numbers_new_images_past_the_ones_it_holds() {
        let mut shell = attaching();
        let mut saved = replay(Some("pictures"), Vec::new());
        saved.next_image = 5;
        shell.hydrate(saved, false);
        shell.route_bytes(b"/image shot.png\r");
        assert_eq!(attached_ids(&shell), [5]);
    }

    // -----------------------------------------------------------------------
    // `/usage` and `/credits`
    // -----------------------------------------------------------------------

    /// The band's rows with every colour taken off.
    fn usage_band(shell: &Fixture) -> Vec<String> {
        shell
            .band_rows()
            .iter()
            .map(|row| colourless(row))
            .collect()
    }

    /// 2026-10-12 15:30 UTC, the capture harness's pinned clock
    /// (`scripts/fxcap/scenarios/p5-usage-cached.cap`).
    const USAGE_NOW: i64 = 1_791_819_000_000;
    /// The fake key every `/usage` case asks with; never on a screen.
    const USAGE_KEY: &str = "fake-key-usage-shell-must-not-appear";

    /// A `/usage` runtime the case drives: a clock it moves, a usage cache in
    /// a home of its own, and a spawner that keeps every fetch it is asked to
    /// start -- holding it, so it is "in flight" until the case runs it.
    struct UsageRig {
        now: Arc<std::sync::atomic::AtomicI64>,
        jobs: Arc<std::sync::Mutex<Vec<crate::usage::report::Job>>>,
        home: tempfile::TempDir,
    }

    impl UsageRig {
        fn put_in(shell: &mut Fixture) -> Self {
            let now = Arc::new(std::sync::atomic::AtomicI64::new(USAGE_NOW));
            let jobs = Arc::new(std::sync::Mutex::new(Vec::new()));
            let home = tempfile::tempdir().expect("a home");
            let clock: crate::usage::dashboard::Clock = {
                let now = Arc::clone(&now);
                Arc::new(move || now.load(Ordering::SeqCst))
            };
            let held = Arc::clone(&jobs);
            let spawn: crate::usage::dashboard::Spawn = Box::new(move |job| {
                held.lock().expect("the jobs").push(job);
                std::thread::Builder::new().spawn(|| {})
            });
            shell.usage_runtime(crate::usage::dashboard::Dashboard::new(
                crate::usage::cache::Home::new(Some(home.path())),
                clock,
                spawn,
            ));
            Self { now, jobs, home }
        }

        /// How many fetches the runtime has started.
        fn started(&self) -> usize {
            self.jobs.lock().expect("the jobs").len()
        }

        fn advance(&self, by_ms: i64) {
            self.now.fetch_add(by_ms, Ordering::SeqCst);
        }

        /// Runs the fetch the runtime started `index`th, here.
        fn run(&self, index: usize) {
            let job = {
                let mut jobs = self.jobs.lock().expect("the jobs");
                std::mem::replace(&mut jobs[index], Box::new(|| {}))
            };
            job();
        }

        /// A usage cache for `question` holding today's numbers and the
        /// finished days, fetched five minutes ago.
        fn seed(&self, question: &crate::usage::report::Question, models: &[(&str, f64)]) {
            use crate::usage::cache::{Entry, Finished, Today};
            let now = self.now.load(Ordering::SeqCst);
            let day = crate::usage::report::utc_day(now);
            let rows: Vec<crate::usage::report::ModelRow> = models
                .iter()
                .map(|(model, cost)| crate::usage::report::ModelRow {
                    model: (*model).to_string(),
                    totals: crate::usage::report::Totals {
                        request_count: 3,
                        input_tokens: 1000,
                        total_cost: *cost,
                        ..crate::usage::report::Totals::default()
                    },
                })
                .collect();
            let at_ms = now - 5 * 60 * 1000;
            let entry = Entry {
                today: Some(Today {
                    day,
                    at_ms,
                    models: rows.clone(),
                }),
                finished: Some(Finished {
                    day,
                    at_ms,
                    days_7: rows.clone(),
                    month: rows,
                }),
                budget: None,
            };
            let home = crate::usage::cache::Home::new(Some(self.home.path())).expect("a home");
            crate::usage::cache::store(&home, &question.identity(), entry, now, None)
                .expect("the cache is written");
        }
    }

    /// What `/usage` asks with `key` for a Gateway at `origin`: the question
    /// a runtime publishes for that configuration.
    fn usage_question_at(origin: &str, key: &str) -> crate::usage::report::Question {
        let home = tempfile::tempdir().expect("a home");
        let workspace = tempfile::tempdir().expect("a workspace");
        let config = RuntimeConfig::load_with(
            &crate::config::Environment::new(
                Some(home.path().to_path_buf()),
                BTreeMap::from([("AI_GATEWAY_API_KEY".to_string(), key.to_string())]),
            ),
            workspace.path(),
        )
        .expect("load a configuration");
        let endpoint =
            crate::gateway::Endpoint::resolve(Some(&format!("{origin}/v4/ai/language-model")))
                .expect("a loopback endpoint");
        crate::usage::report::question(&config, &endpoint).expect("a key is asked")
    }

    /// A loopback port that counts the connections made to it for `listen`,
    /// answering none of them.
    fn counting_port(listen: Duration) -> (String, std::thread::JoinHandle<usize>) {
        let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("a port");
        listener.set_nonblocking(true).expect("a polled listener");
        let origin = format!(
            "http://127.0.0.1:{}",
            listener.local_addr().expect("an address").port()
        );
        let counted = std::thread::spawn(move || {
            let until = Instant::now() + listen;
            let mut connections = 0;
            while Instant::now() < until {
                match listener.accept() {
                    Ok(_) => connections += 1,
                    Err(_) => std::thread::sleep(Duration::from_millis(2)),
                }
            }
            connections
        });
        (origin, counted)
    }

    #[test]
    fn usage_opens_the_dashboard_in_place_of_the_composer_and_writes_nothing() {
        // `new/nokey-40x120-open@481104fd`: no composer row, the dashboard
        // between two rules, its key help on the hint row -- with xfx's own
        // no-sign-in text.
        let mut shell = shell(40, 120);
        shell.route_bytes(b"/usage\r");
        assert!(shell.document().is_empty(), "/usage wrote to the document");
        assert!(shell.usage_menu.is_some());
        assert_eq!(shell.geometry.input_rows(), 0, "the composer kept its row");
        assert_eq!(
            usage_band(&shell)[1..4],
            [
                "usage: not signed in to AI Gateway",
                "",
                "  (set AI_GATEWAY_API_KEY)"
            ]
        );
        assert_eq!(
            usage_band(&shell).last().map(String::as_str),
            Some("esc close")
        );
        assert!(shell.band_rows().last().unwrap().starts_with(PALETTE.dim()));
        assert!(shell.sent.try_recv().is_err(), "/usage reached the runtime");
        // `r` there asks nothing, and Escape closes it.
        shell.route_bytes(b"r");
        escape(&mut shell);
        assert!(shell.usage_menu.is_none());
        assert_eq!(shell.geometry.input_rows(), 1);
        assert_eq!(shell.hint(), IDLE_HINT);
    }

    /// S1: the key is sent only while `/usage` is up. Nothing at launch, nothing
    /// while it is closed -- the 15-minute timer included -- and nothing after
    /// the session ends; opening asks once, past the minute's floor.
    #[test]
    fn usage_asks_nothing_at_launch_while_closed_or_after_quit() {
        let mut shell = shell(40, 120);
        let rig = UsageRig::put_in(&mut shell);
        let (origin, counted) = counting_port(Duration::from_secs(3));
        shell
            .work
            .publish_usage(Ok(usage_question_at("http://127.0.0.1:9", USAGE_KEY)));
        for _ in 0..3 {
            shell.settle_band(Instant::now());
        }
        assert_eq!(rig.started(), 0, "a fetch at launch");

        shell.route_bytes(b"/usage\r");
        assert_eq!(rig.started(), 1, "opening fetches");
        assert!(shell.usage.is_open());
        escape(&mut shell);
        assert!(shell.usage_menu.is_none() && !shell.usage.is_open());
        // An hour of passes with the screen closed: no timer, no fetch.
        for _ in 0..4 {
            rig.advance(16 * 60 * 1000);
            shell.settle_band(Instant::now());
        }
        assert_eq!(rig.started(), 1, "a fetch while /usage was closed");

        // The same key on another origin, past the key's floor: the fetch the
        // close left running is let go of, and one starts for the new origin.
        shell
            .work
            .publish_usage(Ok(usage_question_at(&origin, USAGE_KEY)));
        shell.route_bytes(b"/usage\r");
        assert_eq!(rig.started(), 2);
        // It is out, so neither `r` nor the timer starts another.
        shell.route_bytes(b"r");
        rig.advance(16 * 60 * 1000);
        shell.settle_band(Instant::now());
        assert_eq!(rig.started(), 2, "a second fetch beside one in flight");
        escape(&mut shell);

        shell.route_bytes(b"/quit\r");
        assert!(shell.leaving());
        // Quit let go of the key: both fetches were cancelled, so run now they
        // ask nobody.
        rig.run(1);
        rig.run(0);
        assert_eq!(counted.join().expect("the port"), 0, "a fetch after quit");
        // And nothing opens or fetches after it.
        shell.usage.open(usage_question_at(&origin, USAGE_KEY));
        assert!(!shell.usage.refresh());
        shell.settle_band(Instant::now());
        assert_eq!(rig.started(), 2, "a fetch after quit");
    }

    /// S1, the switch: a provider switch landing while `/usage` is closed
    /// cancels the fetch the old key has in flight -- run afterwards, it
    /// connects to nobody -- and one landing with it up opens it again on the
    /// new sign-in. (A resume onto another provider is the next case.)
    #[test]
    fn a_sign_in_switch_cancels_the_fetch_the_old_key_has_in_flight() {
        let mut shell = shell(40, 120);
        let rig = UsageRig::put_in(&mut shell);
        let (origin, counted) = counting_port(Duration::from_secs(2));
        shell
            .work
            .publish_usage(Ok(usage_question_at(&origin, USAGE_KEY)));
        shell.route_bytes(b"/usage\r");
        assert_eq!(rig.started(), 1);
        escape(&mut shell);
        // The switch: the runtime publishes the new sign-in, then says so.
        shell
            .work
            .publish_usage(Err(crate::usage::report::Unavailable::UnsupportedProvider));
        shell.apply(UiEvent::ProviderSelected {
            provider: ProviderId::Llmux,
            model: "fable".to_string(),
            missing_credential: false,
        });
        rig.run(0);
        assert_eq!(counted.join().expect("the port"), 0, "the old key was sent");
        // The next `/usage` says why it has nothing, and asks nobody.
        shell.route_bytes(b"/usage\r");
        assert_eq!(
            usage_band(&shell)[1],
            "usage: this provider's usage isn't shown yet"
        );
        assert_eq!(rig.started(), 1);

        // A switch landing **with the screen up** opens it again on the new
        // sign-in, keeping the screen: another key, so another floor.
        shell.work.publish_usage(Ok(usage_question_at(
            "http://127.0.0.1:9",
            "another-fake-key",
        )));
        shell.apply(UiEvent::ProviderSelected {
            provider: ProviderId::Gateway,
            model: "fake/model-a".to_string(),
            missing_credential: false,
        });
        assert!(shell.usage_menu.is_some());
        assert_eq!(rig.started(), 2);
        assert!(usage_band(&shell)[1].starts_with("usage: API key (AI_GATEWAY_API_KEY)"));
    }

    /// S1, the resume: a session resumed onto another provider -- the replay's
    /// `provider` -- with `/usage` closed cancels the fetch the old key has in
    /// flight, as a switch does (`hydrate_as` -> `usage_sign_in_changed`).
    #[test]
    fn a_resume_onto_another_provider_cancels_the_fetch_the_old_key_has_in_flight() {
        let mut shell = shell(40, 120);
        let rig = UsageRig::put_in(&mut shell);
        let (origin, counted) = counting_port(Duration::from_secs(2));
        shell
            .work
            .publish_usage(Ok(usage_question_at(&origin, USAGE_KEY)));
        shell.route_bytes(b"/usage\r");
        assert_eq!(rig.started(), 1);
        escape(&mut shell);
        assert!(shell.usage_menu.is_none());
        // The runtime publishes the resumed session's sign-in, then the band
        // hydrates it.
        shell
            .work
            .publish_usage(Err(crate::usage::report::Unavailable::UnsupportedProvider));
        let mut resumed = replay(Some("resumed on llmux"), Vec::new());
        resumed.provider = Some((ProviderId::Llmux, false));
        shell.apply(UiEvent::Resumed(resumed));
        assert_eq!(shell.provider, ProviderId::Llmux);
        rig.run(0);
        assert_eq!(counted.join().expect("the port"), 0, "the old key was sent");
        // And the next `/usage` says why it has nothing, asking nobody.
        shell.route_bytes(b"/usage\r");
        assert_eq!(
            usage_band(&shell)[1],
            "usage: this provider's usage isn't shown yet"
        );
        assert_eq!(rig.started(), 1);
    }

    #[test]
    fn the_screen_draws_the_cache_at_once_and_the_keys_walk_it() {
        // `new/cached-40x120-*@481104fd`: the cache drawn with `updating…`
        // while the fetch is out; ↓, Enter, ↓ on the details, Tab doing
        // nothing there, Escape back, Tab, Right, Left, Shift-Tab, C-j, C-k.
        let mut shell = shell(40, 120);
        let rig = UsageRig::put_in(&mut shell);
        let question = usage_question_at("http://127.0.0.1:9", USAGE_KEY);
        rig.seed(
            &question,
            &[("anthropic/claude-opus-5", 19.17), ("openai/gpt-5.6", 4.10)],
        );
        shell.work.publish_usage(Ok(question));
        shell.route_bytes(b"/usage\r");
        let band = usage_band(&shell);
        assert!(
            band[1].starts_with("usage: API key (AI_GATEWAY_API_KEY)"),
            "{band:?}"
        );
        assert!(band[1].ends_with("updating\u{2026}"), "{band:?}");
        assert_eq!(band[3], "period        spent  requests  tokens");
        assert_eq!(
            band[8],
            "  model (month)                spent   share  requests  tokens"
        );
        assert!(
            band[9].starts_with("\u{276f} anthropic/claude-opus-5"),
            "{band:?}"
        );
        assert_eq!(
            band.last().map(String::as_str),
            Some("\u{2191}\u{2193} model     enter detail     tab period     r refresh     esc close")
        );
        // The caret on the selected row.
        assert_eq!(shell.cursor(), (shell.geometry.panel_first() + 8, 0));

        shell.route_bytes(b"\x1b[B");
        assert!(usage_band(&shell)[10].starts_with("\u{276f} openai/gpt-5.6"));
        shell.route_bytes(b"\r");
        let detail = usage_band(&shell);
        assert!(
            detail[1].starts_with("usage: openai/gpt-5.6, model 2 of 2"),
            "{detail:?}"
        );
        assert_eq!(shell.geometry.panel, 16);
        assert_eq!(
            detail.last().map(String::as_str),
            Some("\u{2191}\u{2193} next model     esc back     r refresh")
        );
        shell.route_bytes(b"\x1b[A");
        assert!(usage_band(&shell)[1].starts_with("usage: anthropic/claude-opus-5, model 1 of 2"));
        shell.route_bytes(b"\t");
        assert!(
            usage_band(&shell)[1].contains("model 1 of 2"),
            "Tab on the details"
        );
        escape(&mut shell);
        assert!(
            shell.usage_menu.is_some(),
            "Escape on the details closed it"
        );
        assert!(usage_band(&shell)[9].starts_with("\u{276f} anthropic"));

        for (keys, period) in [
            (&b"\t"[..], "today"),
            (b"\t", "7d"),
            (b"\x1b[C", "month"),
            (b"\x1b[D", "7d"),
            (b"\x1b[Z", "today"),
            (b"\x1b[Z", "month"),
        ] {
            shell.route_bytes(keys);
            assert!(
                usage_band(&shell)[8].starts_with(&format!("  model ({period})")),
                "{keys:?}: {:?}",
                usage_band(&shell)
            );
        }
        shell.route_bytes(b"\n");
        assert!(usage_band(&shell)[10].starts_with("\u{276f} openai"), "C-j");
        shell.route_bytes(&[0x0b]);
        assert!(
            usage_band(&shell)[9].starts_with("\u{276f} anthropic"),
            "C-k"
        );

        // Everything else is swallowed: no letter reaches the hidden
        // composer, Ctrl-D does not leave, Ctrl-C does not reach the runtime.
        shell.route_bytes(b"abc\x7f\x04\x03");
        assert!(shell.editor.is_empty(), "{:?}", shell.editor.text());
        assert!(!shell.leaving(), "Ctrl-D left from behind the dashboard");
        assert_eq!(shell.controlled(), None);
        assert!(shell.document().is_empty());

        // The period is kept across a close; nothing else is.
        shell.route_bytes(b"\t");
        escape(&mut shell);
        assert!(shell.usage_menu.is_none());
        shell.route_bytes(b"/usage\r");
        assert!(usage_band(&shell)[8].starts_with("  model (today)"));
        assert_eq!(rig.started(), 1, "reopened within the floor");
    }

    /// S3: no row the dashboard draws -- the heading included, in any state
    /// -- shows the key; the heading names the variable.
    #[test]
    fn no_usage_screen_shows_the_key() {
        let mut shell = shell(40, 120);
        // A spawner that refuses is a fetch that fails: the failure state.
        let question = usage_question_at("http://127.0.0.1:9", USAGE_KEY);
        shell.work.publish_usage(Ok(question.clone()));
        shell.route_bytes(b"/usage\r");
        let band = usage_band(&shell);
        assert_eq!(
            band[1],
            format!(
                "usage: API key (AI_GATEWAY_API_KEY){}couldn't reach AI Gateway",
                " ".repeat(120 - 35 - 25)
            )
        );
        let rig = UsageRig::put_in(&mut shell);
        rig.seed(&question, &[("anthropic/claude-opus-5", 1.0)]);
        escape(&mut shell);
        shell.route_bytes(b"/usage\r");
        shell.route_bytes(b"\r");
        for cols in [120, 50, 40] {
            shell.resize(40, cols);
            for row in shell.band_rows() {
                assert!(!row.contains(USAGE_KEY), "{row:?}");
            }
        }
        assert!(!format!("{:?}", shell.usage_menu).contains(USAGE_KEY));
    }

    #[test]
    fn usage_and_credits_take_nothing_after_them() {
        // `fx-credits-404-40x120-arg`: `/credits now` is a command nobody has.
        // And `/cost`, which v0.0.16 dropped (`commands.zig:454@481104fd`).
        for line in ["/usage 7d", "/cost", "/credits now", "/balance x"] {
            let mut shell = shell(24, 80);
            shell.route_bytes(format!("{line}\r").as_bytes());
            assert_eq!(
                shell.document(),
                said(notice::Notice::error(
                    "command",
                    "Unknown command. Try /help."
                )),
                "{line}"
            );
            assert!(shell.usage_menu.is_none(), "{line}");
            assert!(shell.sent.try_recv().is_err(), "{line}");
        }
    }

    /// What `/credits` asks with a Gateway key: the question a runtime
    /// publishes for this configuration.
    fn a_credits_question() -> crate::credits::Question {
        let home = tempfile::tempdir().expect("a home");
        let workspace = tempfile::tempdir().expect("a workspace");
        let config = RuntimeConfig::load_with(
            &crate::config::Environment::new(
                Some(home.path().to_path_buf()),
                BTreeMap::from([("AI_GATEWAY_API_KEY".to_string(), "key".to_string())]),
            ),
            workspace.path(),
        )
        .expect("load a configuration");
        crate::credits::question(&config).expect("a Gateway with a key asks")
    }

    #[test]
    fn credits_is_asked_at_once_and_answered_as_upstreams_notice() {
        let mut shell = shell(40, 120);
        shell.work.publish_credits(Ok(a_credits_question()));
        shell.route_bytes(b"/balance\r");
        assert_eq!(shell.credit_asks.asked(), 1);
        assert!(shell.sent.try_recv().is_err(), "/credits was queued");
        assert!(shell.document().is_empty(), "answered before it was asked");

        // `fx-credits-ok-40x120-after`: three fields, one per row, the later
        // two under the first's gutter.
        shell.credit_asks.deliver(crate::credits::Answer::Credits {
            balance: Some("42.17".to_string()),
            used: Some("7.83".to_string()),
            plan: Some("pro".to_string()),
        });
        shell.settle_band(Instant::now());
        assert_eq!(
            shell.document(),
            ["* credits: balance=42.17", "  used=7.83", "  plan=pro", ""]
        );
        // `credits-empty`: neutral, and says there was nothing.
        shell.credit_asks.deliver(crate::credits::Answer::Credits {
            balance: None,
            used: None,
            plan: None,
        });
        shell.settle_band(Instant::now());
        assert_eq!(
            shell.document(),
            said(notice::Notice::neutral(
                "credits",
                "no data returned by gateway"
            ))
        );
        // `credits-404`: an error, in the error tone.
        shell.credit_asks.deliver(crate::credits::Answer::Failed(
            "HTTP 404: not found".to_string(),
        ));
        shell.settle_band(Instant::now());
        let rows = shell.take_pending();
        let row = &rows[0].rows[0];
        assert_eq!(colourless(row), "\u{2717} credits: HTTP 404: not found");
        // The glyph and topic in the outcome label's grey, the body in the
        // notice grey (`\e[38;5;252m✗ credits:\e[38;5;250m HTTP 404…`).
        assert!(row.starts_with(PALETTE.notice_label()), "{row:?}");
        assert!(
            row.contains(&format!("{} HTTP 404: not found", PALETTE.notice())),
            "{row:?}"
        );
    }

    /// Upstream answers `/credits` on the spot (`commandShowCredits`,
    /// `app_commands.zig:2052-2082`): a turn that is running does not hold it,
    /// a full queue does not refuse it, and a Ctrl-C meant for the turn does
    /// not take it away.
    #[test]
    fn credits_with_a_turn_running_and_the_queue_full_is_asked_and_survives_a_ctrl_c() {
        let mut shell = shell(24, 80);
        shell.work.publish_credits(Ok(a_credits_question()));
        shell.route_bytes(b"first\r");
        shell.route_bytes(b"second\r");
        shell.start_turn();
        shell.document();
        shell.route_bytes(b"/credits\r");
        assert_eq!(shell.credit_asks.asked(), 1, "/credits waited");
        assert!(!shell.hint().contains(QUEUE_REJECTED), "{}", shell.hint());
        assert_eq!(shell.picks_up(), TurnWork::Submit("first".to_string()));
        assert_eq!(shell.picks_up(), TurnWork::Submit("second".to_string()));
        assert!(shell.sent.try_recv().is_err(), "/credits joined the queue");

        // The interrupt is the turn's, and the question is not.
        shell.route_bytes(&[0x03]);
        assert!(
            matches!(shell.control.try_recv(), Ok(TurnControl::Cancel { .. })),
            "the Ctrl-C did not interrupt the turn"
        );
        shell.credit_asks.deliver(crate::credits::Answer::Credits {
            balance: Some("42.17".to_string()),
            used: None,
            plan: None,
        });
        shell.settle_band(Instant::now());
        assert!(
            shell
                .document()
                .iter()
                .any(|row| row == "* credits: balance=42.17"),
            "the answer was dropped"
        );
    }

    #[test]
    fn credits_with_nothing_to_ask_answers_at_once_and_asks_nobody() {
        let mut shell = shell(40, 120);
        shell
            .work
            .publish_credits(Err(crate::credits::Answer::Failed(
                crate::output::MISSING_AUTH_HELP.to_string(),
            )));
        shell.route_bytes(b"/credits\r");
        assert_eq!(shell.credit_asks.asked(), 0);
        assert_eq!(
            shell.document(),
            said(notice::Notice::error(
                "credits",
                crate::output::MISSING_AUTH_HELP
            ))
        );
    }

    // -----------------------------------------------------------------------
    // `/settings`: the menu, its keys, and each row's change
    // -----------------------------------------------------------------------

    /// The settings menu's key help as the hint row paints it at 120 columns.
    fn settings_key_help() -> String {
        format!(
            "{}{}{}",
            PALETTE.dim(),
            settings::key_help(120),
            PALETTE.reset()
        )
    }

    /// The menu's rows with their colours taken out.
    fn settings_text(shell: &Shell) -> Vec<String> {
        menu(shell).iter().map(|row| visible_text(row)).collect()
    }

    /// A `shell_at_home` with `/settings` up.
    fn with_settings(root: &std::path::Path) -> Fixture {
        let mut shell = shell_at_home(root, 40, 120);
        shell.route_bytes(b"/settings\r");
        assert!(shell.settings_menu.is_some(), "/settings opened no menu");
        shell
    }

    /// `n` presses of Down.
    fn down(shell: &mut Fixture, n: usize) {
        for _ in 0..n {
            shell.route_bytes(b"\x1b[B");
        }
    }

    const RIGHT: &[u8] = b"\x1b[C";
    const LEFT: &[u8] = b"\x1b[D";

    /// The saved line a `/settings` preference announces under `topic`.
    fn settings_saved(topic: &str) -> Vec<String> {
        said(notice::Notice::neutral(
            topic,
            interactive::STATUSLINE_SAVED,
        ))
    }

    #[test]
    fn a_bare_settings_opens_upstreams_menu_under_the_composer() {
        // `cap/fx-settings-40x120-bare`: the composer row stays, the rule, the
        // header and a blank, a row per setting with the first marked, the
        // rule and the key help -- and nothing written anywhere.
        let root = tempfile::tempdir().expect("a root");
        let mut shell = with_settings(root.path());
        assert!(shell.document().is_empty(), "the menu wrote a notice");
        assert_eq!(shell.geometry.input_rows(), 1, "the composer lost its row");
        assert_eq!(shell.geometry.panel, 16);
        let model = format!("  Model                    {}", shell.model);
        assert_eq!(
            settings_text(&shell),
            [
                "Settings 14  [All]  Interface  Agent  Notifications  Advanced",
                "",
                "  Status line context      off  on",
                "  Status line session      off  on",
                "  Status line workspace    off  on",
                "  Slash menu categories    off  on",
                "  Collapse tool calls      off  on",
                model.as_str(),
                "  Reasoning effort         default",
                "  Fast mode                off",
                "  Ultra mode               off",
                "  Permission mode          ask  auto  full access",
                "  Session titles           off  on",
                "  Sound level              off  on",
                "  Startup scrollback       off  on",
                "  Prompt history           off  on",
            ]
        );
        let rows = menu(&shell);
        let (bright, dim, reset) = (PALETTE.subtitle(), PALETTE.dim(), PALETTE.reset());
        assert_eq!(
            rows[2],
            format!("  {bright}Status line context{reset}      {bright}off{reset}  {dim}on{reset}")
        );
        assert_eq!(
            rows[5],
            format!("  {dim}Slash menu categories{reset}    {dim}off{reset}  {bright}on{reset}")
        );
        assert_eq!(shell.band_rows().last(), Some(&settings_key_help()));
        // A view of the composer: the caret stays in it.
        assert_eq!(
            shell.cursor(),
            (shell.geometry.input_first, PROMPT_CELLS),
            "the menu took the caret"
        );
        assert_eq!(profile_at(root.path()), "", "opening it wrote the profile");
        // The one thing it asks the runtime for is the catalog its effort and
        // speed rows read.
        assert_eq!(
            shell.controlled(),
            Some(TurnControl::Catalog(CatalogAsk::TOLD))
        );
        assert!(
            shell.sent.try_recv().is_err(),
            "/settings asked the runtime for more than the catalog"
        );
    }

    #[test]
    fn typing_is_the_search_and_escape_closes_the_menu_and_empties_it() {
        // `fx-settings2-40x120-filter-sou`, `-filter-none`, `-esc`.
        let root = tempfile::tempdir().expect("a root");
        let mut shell = with_settings(root.path());
        shell.route_bytes(b"sou");
        assert_eq!(shell.editor.text(), "sou");
        assert!(shell.picker.is_none());
        assert_eq!(
            settings_text(&shell),
            [
                "Settings 2  [All]  Interface  Agent  Notifications  Advanced",
                "",
                "  Slash menu categories    off  on",
                "  Sound level              off  on",
            ]
        );
        assert_eq!(shell.geometry.panel, 4, "the band follows the search");
        shell.route_bytes(b"zzz");
        assert_eq!(
            settings_text(&shell)[2..],
            ["No settings found.".to_string()]
        );
        // A slash word typed into it is its search, not a command.
        shell.route_bytes(&[0x15]);
        shell.route_bytes(b"/");
        assert!(shell.picker.is_none(), "the completion menu opened over it");
        escape(&mut shell);
        assert!(shell.settings_menu.is_none());
        assert!(shell.editor.is_empty(), "{:?}", shell.editor.text());
        assert_eq!(shell.geometry.panel, 0);
        assert_eq!(shell.hint(), IDLE_HINT);
        assert!(shell.document().is_empty());
    }

    #[test]
    fn nothing_typed_into_the_search_opens_another_picker_and_c_p_is_nothing_over_it() {
        // The draft is the menu's search: an `@` word is no file query, a
        // `/model ` line no model column, and C-p -- blocked by a menu that
        // owns the keyboard (`modelPickerShortcutBlocked`,
        // `app_input_runtime.zig:2408-2410`) -- opens no catalog.
        let root = tempfile::tempdir().expect("a root");
        let mut shell = with_settings(root.path());
        // The menu's own ask, for its effort and speed rows; nothing typed
        // into the search asks for another.
        assert_eq!(
            shell.controlled(),
            Some(TurnControl::Catalog(CatalogAsk::TOLD))
        );
        shell.route_bytes(b"@src");
        assert!(
            shell.file_picker.is_none(),
            "an @ word opened the file picker"
        );
        shell.route_bytes(&[0x15]);
        shell.route_bytes(b"/model ");
        assert!(shell
            .column
            .active(shell.editor.text(), &shell.model)
            .is_some());
        assert!(
            !matches!(shell.slot(), Some(Slot::Column)),
            "the model column took the slot"
        );
        shell.route_bytes(b"x");
        assert_eq!(shell.editor.text(), "/model x");
        assert!(
            shell.sent.try_recv().is_err(),
            "the search asked for a catalog"
        );
        shell.route_bytes(&[0x10]);
        assert!(shell.model_menu.is_none(), "C-p opened the model catalog");
        assert!(shell.settings_menu.is_some());
        assert_eq!(shell.editor.text(), "/model x");
    }

    #[test]
    fn tab_and_shift_tab_walk_the_categories_and_the_band_follows() {
        // `fx-settings2-40x120-tab1..5`.
        let root = tempfile::tempdir().expect("a root");
        let mut shell = with_settings(root.path());
        shell.route_bytes(b"\t");
        assert_eq!(
            settings_text(&shell)[0],
            "Settings 5  All  [Interface]  Agent  Notifications  Advanced"
        );
        assert_eq!(shell.geometry.panel, 7);
        shell.route_bytes(b"\t");
        assert_eq!(
            settings_text(&shell)[2..],
            [
                format!("  Model               {}", shell.model),
                "  Reasoning effort    default".to_string(),
                "  Fast mode           off".to_string(),
                "  Ultra mode          off".to_string(),
                "  Permission mode     ask  auto  full access".to_string(),
                "  Session titles      off  on".to_string(),
            ]
        );
        // Shift-Tab is the category back, and not the permission mode.
        shell.route_bytes(b"\x1b[Z");
        assert!(settings_text(&shell)[0].contains("[Interface]"));
        assert_eq!(shell.mode, PermissionMode::Auto);
        shell.route_bytes(b"\x1b[Z\x1b[Z");
        assert_eq!(
            settings_text(&shell),
            [
                "Settings 2  All  Interface  Agent  Notifications  [Advanced]",
                "",
                "  Startup scrollback    off  on",
                "  Prompt history        off  on",
            ]
        );
        assert_eq!(shell.mode, PermissionMode::Auto);
    }

    #[test]
    fn up_and_down_wrap_and_enter_changes_nothing_on_a_setting() {
        // `fx-settings2-40x120-enter` is `-sound-right` again: Enter is inert
        // everywhere but on `Model` (trap b: the statusline picker is the one
        // whose Enter flips).
        let root = tempfile::tempdir().expect("a root");
        let mut shell = with_settings(root.path());
        shell.route_bytes(b"\x1b[A");
        assert!(visible_text(&menu(&shell)[15]).starts_with("  Prompt history"));
        assert_eq!(menu(&shell)[15].matches(PALETTE.subtitle()).count(), 2);
        let before = shell.band_rows();
        shell.route_bytes(b"\r");
        assert_eq!(shell.band_rows(), before);
        assert!(shell.settings_menu.is_some());
        assert!(shell.recall.enabled);
        assert!(shell.document().is_empty());
        assert_eq!(profile_at(root.path()), "");
        down(&mut shell, 1);
        assert_eq!(menu(&shell)[2].matches(PALETTE.subtitle()).count(), 2);
    }

    #[test]
    fn right_on_a_status_line_row_is_statusline_item_and_says_both_notices() {
        // `fx-settings2-40x120-right-context`: the two notices above the
        // still-open menu, the row's `on` bold, and the profile written.
        let root = tempfile::tempdir().expect("a root");
        let mut shell = with_settings(root.path());
        shell.route_bytes(RIGHT);
        assert_eq!(shell.document(), flipped("context", true));
        assert!(shell.statusline.context);
        assert!(shell.settings_menu.is_some(), "a change closed the menu");
        assert_eq!(
            settings_text(&shell)[2],
            "  Status line context      off  on"
        );
        assert!(menu(&shell)[2].ends_with(&format!("{}on{}", PALETTE.subtitle(), PALETTE.reset())));
        assert_eq!(
            profile_at(root.path()),
            "{\n  \"statusLine\": {\n    \"context\": true\n  }\n}\n"
        );
        // Left wraps back to off, and says so the same way.
        shell.route_bytes(LEFT);
        assert_eq!(shell.document(), flipped("context", false));
        assert!(!shell.statusline.context);
        // The workspace segment shows on the hint row at once.
        down(&mut shell, 2);
        shell.route_bytes(RIGHT);
        assert_eq!(shell.document(), flipped("workspace", true));
        escape(&mut shell);
        assert!(
            shell
                .hint()
                .ends_with(&shell.workspace.display().to_string()),
            "{}",
            shell.hint()
        );
    }

    #[test]
    fn right_on_permission_mode_is_permissions_with_the_mode_its_notice_and_the_runtime_told() {
        let (mut shell, mut changes) = permissions_shell(PermissionMode::Auto, true);
        let (mut typed, mut typed_changes) = permissions_shell(PermissionMode::Auto, true);
        shell.route_bytes(b"/settings\r");
        down(&mut shell, 9);
        assert!(visible_text(&menu(&shell)[11]).starts_with("  Permission mode"));
        shell.route_bytes(RIGHT);
        typed.route_bytes(b"/permissions full-access\r");
        assert_eq!(shell.mode, PermissionMode::Yolo);
        assert_eq!(shell.document(), typed.document());
        assert_eq!(changes_sent(&mut changes), changes_sent(&mut typed_changes));
        assert!(settings_text(&shell)[11].ends_with("ask  auto  full access"));
        assert_eq!(
            menu(&shell)[11].matches(PALETTE.subtitle()).count(),
            2,
            "the marked label and `full access`"
        );
        // Right again wraps to ask.
        shell.route_bytes(RIGHT);
        typed.route_bytes(b"/permissions ask\r");
        assert_eq!(shell.mode, PermissionMode::Ask);
        assert_eq!(shell.document(), typed.document());
    }

    #[test]
    fn right_on_sound_level_is_sound_on_and_saves_both_switches() {
        // `fx-settings2-40x120-sound-right`: `* sound: on`.
        let (_home, path) = profile();
        let mut shell = sounding(40, false, Some(path.clone()));
        shell.route_bytes(b"/settings\r");
        down(&mut shell, 11);
        shell.route_bytes(RIGHT);
        assert_eq!(
            shell.released(),
            said(notice::Notice::neutral("sound", "on"))
        );
        assert_eq!(
            shell.sound.notifications(),
            crate::config::Notifications::both(true)
        );
        saved_as(
            &path,
            serde_json::json!({"notifications": {"turn_end": true, "attention_required": true}}),
        );
        assert!(settings_text(&shell)[13].ends_with("Sound level              off  on"));
    }

    #[test]
    fn right_on_session_titles_switches_them_saves_and_is_in_force_for_the_runtime() {
        // `applySettingsCatalogChange`'s `.session_titles`
        // (`app_commands.zig:4149-4166`): in force at once, saved, and
        // announced as `persistUserPreferences` announces.
        let root = tempfile::tempdir().expect("a root");
        let mut shell = with_settings(root.path());
        assert!(shell.work.session_titles(), "upstream's default is on");
        down(&mut shell, 10);
        assert_eq!(
            settings_text(&shell)[12],
            "  Session titles           off  on"
        );
        shell.route_bytes(RIGHT);
        assert!(!shell.work.session_titles());
        assert_eq!(
            shell.document(),
            said(notice::Notice::neutral(
                settings::SESSION_TITLES_TOPIC,
                interactive::STATUSLINE_SAVED
            ))
        );
        assert_eq!(
            profile_at(root.path()),
            "{\n  \"session_titles\": false\n}\n"
        );
        shell.route_bytes(RIGHT);
        assert!(shell.work.session_titles());
        assert_eq!(
            profile_at(root.path()),
            "{\n  \"session_titles\": true\n}\n"
        );
    }

    /// A 40x120 shell at a home of its own, holding the harness's catalog,
    /// on `openai/gpt-6-astra` (`p5-effort-fork-seed-astra.json`).
    fn effort_shell(root: &std::path::Path) -> Fixture {
        effort_shell_at(root, 40, 120)
    }

    /// [`effort_shell`] on a screen of `rows` x `cols`.
    fn effort_shell_at(root: &std::path::Path, rows: u16, cols: u16) -> Fixture {
        let mut shell = shell_at_home(root, rows, cols);
        shell.apply(UiEvent::CatalogLoaded {
            due: CatalogDue::at(catalog_now() + crate::provider::model::REFRESH_INTERVAL),
            provider: ProviderId::Gateway,
            entries: harness_rows(),
        });
        shell.model = "openai/gpt-6-astra".to_string();
        let _ = shell.document();
        shell
    }

    /// `/effort`'s rows as the band paints them, as text.
    fn effort_text(shell: &Shell) -> Vec<String> {
        menu(shell).iter().map(|row| visible_text(row)).collect()
    }

    fn effort_said(body: &str) -> Vec<String> {
        said(notice::Notice::neutral(settings::EFFORT_TOPIC, body))
    }

    #[test]
    fn a_bare_effort_opens_the_menu_whose_keys_wrap_and_whose_enter_names_the_level() {
        // `fx-p5-effort-fork-effort-menu-40x120-menu`, `-menu-down`,
        // `-menu-wrap`, `-menu-esc`, `-menu-enter`.
        let root = tempfile::tempdir().expect("a root");
        let mut shell = effort_shell(root.path());
        shell.route_bytes(b"/effort\r");
        assert!(matches!(shell.slot(), Some(Slot::Effort(_))));
        assert_eq!(
            effort_text(&shell),
            [
                "Effort 5  openai/gpt-6-astra",
                "",
                "  default  current",
                "  low",
                "  medium",
                "  high",
                "  xhigh",
            ]
        );
        assert_eq!(
            visible_text(&shell.band_rows()[shell.band_rows().len() - 1]),
            "\u{2191}\u{2193} navigate     enter use     esc close"
        );
        // Nothing is written for opening it.
        assert!(shell.document().is_empty());
        down(&mut shell, 1);
        assert_eq!(
            shell.effort_menu.as_ref().map(EffortMenu::selected),
            Some(&Effort::Named("low".to_string()))
        );
        shell.route_bytes(b"\x1b[A\x1b[A");
        assert_eq!(
            shell.effort_menu.as_ref().map(EffortMenu::selected),
            Some(&Effort::Named("xhigh".to_string()))
        );
        escape(&mut shell);
        assert!(shell.effort_menu.is_none());
        assert!(shell.document().is_empty());
        assert_eq!(shell.controlled(), None, "Escape applied a level");

        shell.route_bytes(b"/effort\r");
        down(&mut shell, 2);
        shell.route_bytes(b"\r");
        assert!(shell.effort_menu.is_none());
        // The level and the model, and no `saved to user settings`.
        assert_eq!(
            shell.document(),
            said(notice::Notice::neutral(
                "",
                "Reasoning effort set to medium for openai/gpt-6-astra"
            ))
        );
        assert_eq!(shell.settings.effort, Effort::Named("medium".to_string()));
        assert!(shell.hint().ends_with("medium"), "{}", shell.hint());
        assert_eq!(profile_at(root.path()), "{\n  \"effort\": \"medium\"\n}\n");
        assert_eq!(
            change(&mut shell),
            ModelChange {
                name: "openai/gpt-6-astra".to_string(),
                effort: Some(Effort::Named("medium".to_string())),
                speed: None,
                picker: false,
                announced: true,
                next_turn: false,
                provider: ProviderId::Gateway,
                effort_only: true,
            }
        );
        // It opens on the level in use.
        shell.route_bytes(b"/effort\r");
        assert_eq!(effort_text(&shell)[4], "  medium   current");
    }

    #[test]
    fn the_effort_menu_stays_under_a_first_ctrl_c_and_says_the_next_one_leaves() {
        // `fx-p5-effort-fork-effort-ctrlc-40x120-ctrlc`: the menu stays up,
        // and its key help gives way to the warning in the statusline grey
        // until the window closes (`composeEffortMenuHintRow`,
        // `input_presentation.zig:671-679@481104fd`).
        let root = tempfile::tempdir().expect("a root");
        let mut shell = effort_shell(root.path());
        shell.route_bytes(b"/effort\r");
        let now = Instant::now();
        shell.consume(vec![Input::Action(Action::Cancel)], now);
        shell.settle_band(now);
        assert!(
            shell.effort_menu.is_some(),
            "a first Ctrl-C closed the menu"
        );
        assert_eq!(
            shell.band_rows().last().cloned(),
            Some(format!(
                "{}{EXIT_ARMED}{}",
                PALETTE.statusline(),
                PALETTE.reset()
            ))
        );
        shell.settle_band(now + EXIT_WINDOW);
        assert_eq!(
            shell.band_rows().last().cloned(),
            Some(format!(
                "{}{}{}",
                PALETTE.dim(),
                effort_menu::key_help(120),
                PALETTE.reset()
            ))
        );
        assert!(!shell.leaving());
    }

    #[test]
    fn an_edit_closes_the_effort_menu_and_the_edit_stands() {
        // `fx-p5-effort-fork-effort-menu-40x120-menu-edit`: `x` typed over
        // the menu is in the composer, and the menu is gone.
        let root = tempfile::tempdir().expect("a root");
        let mut shell = effort_shell(root.path());
        shell.route_bytes(b"/effort\r");
        shell.route_bytes(b"x");
        assert!(shell.effort_menu.is_none());
        assert_eq!(shell.editor.text(), "x");
        assert!(menu(&shell).is_empty(), "{:?}", menu(&shell));
        // A paste is an edit too.
        shell.route_bytes(b"\x15/effort\r");
        pasted(&mut shell, "y");
        assert!(shell.effort_menu.is_none());
        assert_eq!(shell.editor.text(), "y");
        assert_eq!(shell.controlled(), None);
    }

    #[test]
    fn effort_with_a_word_applies_it_or_says_which_levels_there_are() {
        // `fx-p5-effort-fork-effort-menu-40x120-level-*`.
        let root = tempfile::tempdir().expect("a root");
        let mut shell = effort_shell(root.path());
        shell.route_bytes(b"/effort high\r");
        assert_eq!(
            shell.document(),
            said(notice::Notice::neutral(
                "",
                "Reasoning effort set to high for openai/gpt-6-astra"
            ))
        );
        assert_eq!(profile_at(root.path()), "{\n  \"effort\": \"high\"\n}\n");
        assert!(change(&mut shell).effort_only);
        for (line, body) in [
            (
                "/effort bogus",
                "bogus is not available for openai/gpt-6-astra; levels: default, low, medium, high, xhigh",
            ),
            (
                "/effort max",
                "max is not available for openai/gpt-6-astra; levels: default, low, medium, high, xhigh",
            ),
            // Not a level at all: nothing typed is repeated back.
            (
                "/effort two words",
                "levels for openai/gpt-6-astra: default, low, medium, high, xhigh",
            ),
            (
                "/effort \u{1b}[2J",
                "levels for openai/gpt-6-astra: default, low, medium, high, xhigh",
            ),
        ] {
            pasted(&mut shell, line);
            shell.route_bytes(b"\r");
            assert_eq!(shell.document(), effort_said(body), "{line:?}");
            assert_eq!(shell.controlled(), None, "{line:?} changed something");
            assert_eq!(shell.settings.effort, Effort::Named("high".to_string()));
        }
        // `fx-p5-effort-fork-effort-column-40x120-level-upper`: the `/effort `
        // column's Enter takes `HIGH` as `high` -- its filter ignores case --
        // and `med` as `medium` (`-level-prefix`).
        for (line, level) in [("/effort HIGH", "high"), ("/effort med", "medium")] {
            pasted(&mut shell, line);
            shell.route_bytes(b"\r");
            assert_eq!(
                shell.document(),
                said(notice::Notice::neutral(
                    "",
                    format!("Reasoning effort set to {level} for openai/gpt-6-astra")
                )),
                "{line:?}"
            );
            assert_eq!(shell.settings.effort, Effort::Named(level.to_string()));
            assert!(change(&mut shell).effort_only);
        }
        // The default's three spellings, any case.
        shell.route_bytes(b"/effort Default\r");
        assert_eq!(
            shell.document(),
            said(notice::Notice::neutral(
                "",
                "Reasoning effort set to default for openai/gpt-6-astra"
            ))
        );
        assert_eq!(shell.settings.effort, Effort::Auto);
        assert_eq!(profile_at(root.path()), "{\n  \"effort\": \"auto\"\n}\n");
        assert!(!shell.hint().contains("high"), "{}", shell.hint());
    }

    #[test]
    fn effort_without_levels_says_why_and_opens_nothing() {
        // `fx-p5-effort-fork-effort-nolevels-40x120-bare`, `-level`; the
        // catalog that failed, `effort-down`; the one still on its way,
        // `effort-loading-early`.
        let root = tempfile::tempdir().expect("a root");
        let mut shell = effort_shell(root.path());
        shell.model = "fake/model-a".to_string();
        for line in [&b"/effort\r"[..], b"/effort high\r"] {
            shell.route_bytes(line);
            assert_eq!(
                shell.document(),
                effort_said("fake/model-a has no levels to choose from")
            );
            assert!(shell.effort_menu.is_none());
        }
        // A model the catalog does not list has none either.
        shell.model = "acme/unlisted".to_string();
        shell.route_bytes(b"/effort\r");
        assert_eq!(
            shell.document(),
            effort_said("acme/unlisted has no levels to choose from")
        );

        let mut loading = shell_at_home(root.path(), 40, 120);
        loading.model = "openai/gpt-6-astra".to_string();
        let _ = loading.document();
        loading.route_bytes(b"/effort\r");
        assert_eq!(
            loading.document(),
            effort_said(
                "levels for openai/gpt-6-astra are still loading; try /effort again in a moment"
            )
        );
        // It asks the runtime for nothing: the launch's read answers.
        assert_eq!(loading.controlled(), None);
        // Nor does its column: an `/effort ` line lists what the catalog
        // already says, where a `/model ` line would ask for it.
        loading.route_bytes(b"/effort ");
        assert_eq!(
            loading.controlled(),
            None,
            "the /effort column asked for the catalog"
        );
        loading.route_bytes(&[0x15]);
        loading.apply(UiEvent::CatalogUnread {
            provider: ProviderId::Gateway,
            retry: None,
            retry_at: CatalogDue::at(catalog_now()),
        });
        let _ = loading.document();
        loading.route_bytes(b"/effort\r");
        assert_eq!(
            loading.document(),
            effort_said("openai/gpt-6-astra has no levels to choose from")
        );
        assert!(profile_at(root.path()).is_empty());
    }

    #[test]
    fn an_effort_given_while_a_turn_runs_is_for_the_next_turn() {
        // `fx-p5-effort-fork-effort-menu-40x120-midturn`: said at once, in
        // the next turn's words, and handed to the runtime as a change that
        // waits for the running turn -- which keeps its own level.
        let root = tempfile::tempdir().expect("a root");
        let mut shell = effort_shell(root.path());
        let _started = turn_running(&mut shell, b"slow turn please\r");
        let _turn = shell.picks_up();
        pasted(&mut shell, "/effort high");
        shell.route_bytes(b"\r");
        assert_eq!(
            shell.document(),
            said(notice::Notice::neutral(
                "",
                "Next turn will use reasoning effort high for openai/gpt-6-astra"
            ))
        );
        let asked = change(&mut shell);
        assert!(asked.next_turn && asked.effort_only, "{asked:?}");
        assert!(shell.hint().ends_with("high"), "{}", shell.hint());
        // The menu's Enter, the same: it opens on `high`, the level in use.
        shell.route_bytes(b"/effort\r");
        down(&mut shell, 1);
        shell.route_bytes(b"\r");
        assert_eq!(
            shell.document(),
            said(notice::Notice::neutral(
                "",
                "Next turn will use reasoning effort xhigh for openai/gpt-6-astra"
            ))
        );
    }

    #[test]
    fn page_keys_move_the_effort_menu_by_the_composers_row_cap_and_wrap() {
        // As `/model`'s menu pages (`ModelAction::Page`): a page is the
        // composer's row cap, and the menu wraps it as it wraps a step
        // (`move` takes any delta with `@mod`, `effort_menu.zig:53-57@481104fd`).
        let root = tempfile::tempdir().expect("a root");
        let mut shell = effort_shell(root.path());
        shell.route_bytes(b"/effort\r");
        let page = usize::from(layout::input_row_limit(shell.geometry.rows));
        let levels = [
            Effort::Auto,
            Effort::Named("low".to_string()),
            Effort::Named("medium".to_string()),
            Effort::Named("high".to_string()),
            Effort::Named("xhigh".to_string()),
        ];
        let marked = |shell: &Fixture| {
            shell
                .effort_menu
                .as_ref()
                .map(|menu| menu.selected().clone())
        };
        shell.route_bytes(b"\x1b[6~");
        assert_eq!(marked(&shell), Some(levels[page % 5].clone()));
        shell.route_bytes(b"\x1b[5~");
        assert_eq!(marked(&shell), Some(Effort::Auto));
        shell.route_bytes(b"\x1b[5~");
        assert_eq!(marked(&shell), Some(levels[(5 - page % 5) % 5].clone()));
        assert!(shell.document().is_empty());
        assert_eq!(shell.controlled(), None);
    }

    #[test]
    fn the_effort_menu_closes_when_the_model_or_the_provider_it_was_opened_for_goes() {
        // Upstream has no rule for an open menu under a model change that
        // lands later, because its changes are commands and typing one closes
        // the menu. Here a change can land after its command -- a model
        // change held behind a turn, a provider switch, a resume -- and the
        // menu closes then, so Enter cannot apply one model's level to another.
        let root = tempfile::tempdir().expect("a root");
        let mut shell = effort_shell(root.path());
        shell.route_bytes(b"/effort\r");
        // A catalog read landing is not one.
        shell.apply(UiEvent::CatalogLoaded {
            due: CatalogDue::at(catalog_now() + crate::provider::model::REFRESH_INTERVAL),
            provider: ProviderId::Gateway,
            entries: harness_rows(),
        });
        assert!(shell.effort_menu.is_some());
        shell.apply(UiEvent::ModelAnswered {
            model: "anthropic/claude-opus-5".to_string(),
            settings: TurnSettings::default(),
            outcome: ModelAnswer::Applied { unverified: None },
            next_turn: false,
            announced: false,
        });
        assert!(shell.effort_menu.is_none(), "the menu outlived its model");
        assert!(menu(&shell).is_empty(), "{:?}", menu(&shell));
        let _ = shell.document();
        while shell.controlled().is_some() {}
        shell.route_bytes(b"\r");
        assert_eq!(
            shell.controlled(),
            None,
            "Enter applied the old model's level"
        );
        assert!(shell.document().is_empty());

        shell.model = "openai/gpt-6-astra".to_string();
        shell.route_bytes(b"/effort\r");
        assert!(shell.effort_menu.is_some());
        shell.apply(UiEvent::ProviderSelected {
            provider: ProviderId::Llmux,
            model: "openai/gpt-6-astra".to_string(),
            missing_credential: false,
        });
        assert!(
            shell.effort_menu.is_none(),
            "the menu outlived its provider"
        );
    }

    #[test]
    fn the_hint_row_ends_on_the_effort_given_after_a_held_model_change() {
        // The band's half of the worker's
        // `an_effort_the_band_saved_after_a_model_change_held_behind_a_turn_is_still_the_files`:
        // a pick held behind the turn, then `/effort high`; the pick's answer
        // moves the hint row to its level, and the runtime's word on the
        // effort applied after it moves it back.
        let root = tempfile::tempdir().expect("a root");
        let mut shell = effort_shell(root.path());
        let _started = turn_running(&mut shell, b"slow turn please\r");
        let _turn = shell.picks_up();
        let low = Effort::Named("low".to_string());
        let high = Effort::Named("high".to_string());
        shell.shell.request_change(ModelChange {
            name: "openai/gpt-6-astra".to_string(),
            effort: Some(low.clone()),
            speed: None,
            picker: true,
            announced: true,
            next_turn: true,
            provider: ProviderId::Gateway,
            effort_only: false,
        });
        pasted(&mut shell, "/effort high");
        shell.route_bytes(b"\r");
        assert!(shell.hint().ends_with("high"), "{}", shell.hint());
        shell.apply(UiEvent::TurnEnded { failure: None });
        shell.apply(UiEvent::ModelAnswered {
            model: "openai/gpt-6-astra".to_string(),
            settings: TurnSettings {
                effort: low,
                ..TurnSettings::default()
            },
            outcome: ModelAnswer::Applied { unverified: None },
            next_turn: true,
            announced: true,
        });
        assert!(shell.hint().ends_with("low"), "{}", shell.hint());
        shell.apply(UiEvent::EffortApplied { effort: high });
        assert!(shell.hint().ends_with("high"), "{}", shell.hint());
        assert_eq!(profile_at(root.path()), "{\n  \"effort\": \"high\"\n}\n");
    }

    #[test]
    fn a_failed_effort_write_is_said_and_the_level_is_still_named() {
        // `reportUserSettingsCommit` drops only the benign line: a write that
        // failed is said, then the announcement.
        let root = tempfile::tempdir().expect("a root");
        let mut shell = effort_shell(root.path());
        shell.settings_path = None;
        shell.route_bytes(b"/effort low\r");
        let document = shell.document();
        assert!(
            document
                .iter()
                .any(|row| row.starts_with("\u{2717} effort:")),
            "{document:?}"
        );
        assert!(
            document
                .iter()
                .any(|row| row == "* Reasoning effort set to low for openai/gpt-6-astra"),
            "{document:?}"
        );
    }

    #[test]
    fn the_effort_menu_and_its_notices_never_show_what_a_terminal_would_obey() {
        // An llmux row's levels and a model id are not held to the Gateway's
        // rule on their way in; the menu offers only parsable names and shows
        // the id on one line with nothing a terminal obeys in it.
        let root = tempfile::tempdir().expect("a root");
        let mut shell = shell_at_home(root.path(), 40, 120);
        let forged = "odd\u{1b}]0;x\u{7}\nmodel";
        shell.apply(UiEvent::CatalogLoaded {
            due: CatalogDue::at(catalog_now() + crate::provider::model::REFRESH_INTERVAL),
            provider: ProviderId::Gateway,
            entries: vec![CatalogEntry {
                id: forged.to_string(),
                aliases: Vec::new(),
                name: None,
                efforts: vec!["low".to_string(), "x\u{1b}[2J".to_string()],
                max_context: None,
                facts: Default::default(),
            }],
        });
        shell.model = forged.to_string();
        let _ = shell.document();
        shell.route_bytes(b"/effort\r");
        let rows = menu(&shell);
        assert!(!rows.concat().contains("\u{1b}]"), "{rows:?}");
        assert!(!rows.concat().contains("\u{1b}[2J"), "{rows:?}");
        assert_eq!(effort_text(&shell)[0], "Effort 2  odd ]0;x  model");
        escape(&mut shell);
        shell.route_bytes(b"/effort nope\r");
        let document = shell.document();
        assert_eq!(
            document,
            effort_said("nope is not available for odd ]0;x  model; levels: default, low")
        );
        // And the announcement of a level applied, from the menu and from the
        // command alike.
        shell.route_bytes(b"/effort\r");
        down(&mut shell, 1);
        shell.route_bytes(b"\r");
        shell.route_bytes(b"/effort default\r");
        let document = shell.document();
        assert!(!document.concat().contains('\u{1b}'), "{document:?}");
        assert!(!document.concat().contains('\u{7}'), "{document:?}");
        assert!(
            document
                .iter()
                .any(|row| row == "* Reasoning effort set to low for odd ]0;x  model"),
            "{document:?}"
        );
        assert!(
            document
                .iter()
                .any(|row| row == "* Reasoning effort set to default for odd ]0;x  model"),
            "{document:?}"
        );
        // The `/effort ` column lists the same parsable names and nothing else.
        shell.route_bytes(b"/effort ");
        assert!(matches!(shell.slot(), Some(Slot::Column)));
        let rows = menu(&shell);
        assert!(!rows.concat().contains("\u{1b}[2J"), "{rows:?}");
        assert_eq!(
            rows.iter()
                .map(|row| visible_text(row).trim().to_string())
                .filter(|row| !row.is_empty())
                .collect::<Vec<_>>(),
            ["default", "low"]
        );
    }

    /// The `/effort ` column's rows, as text, from column ten.
    fn levels_at_ten(levels: &[&str]) -> Vec<String> {
        let mut rows: Vec<String> = levels
            .iter()
            .map(|level| format!("{}{level}", " ".repeat(10)))
            .collect();
        rows.resize(6, String::new());
        rows
    }

    #[test]
    fn the_effort_column_lists_the_levels_under_the_argument_and_the_footer_previews_the_mark() {
        // `fx-p5-effort-fork-effort-column-40x120-col-space`, `-col-down`,
        // `-col-nomatch`: no key help, the hint row the session's own with
        // the marked level in place of the one in force.
        let root = tempfile::tempdir().expect("a root");
        let mut shell = effort_shell(root.path());
        shell.route_bytes(b"/effort low\r");
        let _ = shell.document();
        let _ = change(&mut shell);
        assert!(
            shell.hint().ends_with("gpt-6-astra \u{b7} low"),
            "{}",
            shell.hint()
        );
        // A space opens it on its first row, whatever is in use
        // (`-space-first`), and the footer shows the default as no level.
        shell.route_bytes(b"/effort ");
        assert!(matches!(shell.slot(), Some(Slot::Column)));
        assert_eq!(
            column(&shell),
            levels_at_ten(&["default", "low", "medium", "high", "xhigh"])
        );
        assert!(shell.hint().ends_with("gpt-6-astra"), "{}", shell.hint());
        down(&mut shell, 1);
        assert!(
            shell.hint().ends_with("gpt-6-astra \u{b7} low"),
            "{}",
            shell.hint()
        );
        shell.route_bytes(b"zz");
        assert_eq!(column(&shell)[0], "          no matching effort");
        // Nothing marked: the level in force.
        assert!(
            shell.hint().ends_with("gpt-6-astra \u{b7} low"),
            "{}",
            shell.hint()
        );
        assert!(shell.document().is_empty());
        assert_eq!(shell.controlled(), None);
    }

    #[test]
    fn tab_on_a_bare_effort_marks_the_level_in_use_tab_fills_it_and_enter_applies_it() {
        // `fx-p5-effort-fork-effort-column-40x120-tab-current`, `-col-fill`,
        // `-col-enter`, `-typed-space`, `-typed-down`, `-typed-enter`.
        let root = tempfile::tempdir().expect("a root");
        let mut shell = effort_shell(root.path());
        shell.route_bytes(b"/effort medium\r");
        let _ = shell.document();
        let _ = change(&mut shell);
        shell.route_bytes(b"/effort\t");
        assert_eq!(shell.editor.text(), "/effort ");
        assert!(matches!(shell.slot(), Some(Slot::Column)));
        assert!(shell.hint().ends_with("\u{b7} medium"), "{}", shell.hint());
        down(&mut shell, 1);
        shell.route_bytes(b"\t");
        assert_eq!(shell.editor.text(), "/effort high");
        assert_eq!(column(&shell), levels_at_ten(&["high", "xhigh"]));
        assert!(shell.hint().ends_with("\u{b7} high"), "{}", shell.hint());
        shell.route_bytes(b"\r");
        assert_eq!(shell.editor.text(), "");
        assert_eq!(
            shell.document(),
            said(notice::Notice::neutral(
                "",
                "Reasoning effort set to high for openai/gpt-6-astra"
            ))
        );
        assert_eq!(profile_at(root.path()), "{\n  \"effort\": \"high\"\n}\n");
        assert!(change(&mut shell).effort_only);
        // A space typed in the column goes nowhere; Left is the caret's.
        shell.route_bytes(b"/effort hi ");
        assert_eq!(shell.editor.text(), "/effort hi");
        let caret = shell.cursor().1;
        shell.route_bytes(b"\x1b[D");
        assert_eq!(shell.editor.text(), "/effort hi");
        assert_eq!(shell.cursor().1, caret - 1);
        shell.route_bytes(b"\x1b[C");
        // Enter takes the marked row of a filter that keeps two.
        down(&mut shell, 1);
        assert!(shell.hint().ends_with("\u{b7} xhigh"), "{}", shell.hint());
        shell.route_bytes(b"\r");
        assert_eq!(
            shell.document(),
            said(notice::Notice::neutral(
                "",
                "Reasoning effort set to xhigh for openai/gpt-6-astra"
            ))
        );
        assert_eq!(shell.settings.effort, Effort::Named("xhigh".to_string()));
    }

