    #[test]
    fn fork_says_why_it_cannot_and_takes_no_argument() {
        // `fx-p5-effort-fork-fork-edge-40x120-at-launch`, `-with-arg`,
        // `-midturn` and `-fork-of-empty`; `/fork needs a saved session` is
        // upstream's warning (`openForkMenu`, `app_session_runtime.zig:2073`).
        let mut shell = shell(40, 120);
        forked_menu(&mut shell, Vec::new());
        assert!(shell.fork_menu.is_none());
        assert_eq!(
            shell.document(),
            said(notice::Notice::neutral("session", NOTHING_TO_FORK))
        );
        shell.route_bytes(b"/fork\r");
        assert_eq!(shell.picks_up(), TurnWork::ForkPoints);
        shell.work.give_back();
        shell.apply(UiEvent::ForkPoints(ForkPoints::Unsaved));
        assert_eq!(
            shell.document(),
            said(notice::Notice::warning("session", FORK_UNSAVED))
        );
        // An answer nobody is waiting for opens nothing and says nothing.
        shell.apply(UiEvent::ForkPoints(ForkPoints::Points(three_points())));
        assert!(shell.fork_menu.is_none());
        assert!(shell.document().is_empty());

        shell.route_bytes(b"/fork 2\r");
        assert!(
            shell.sent.try_recv().is_err(),
            "/fork 2 reached the runtime"
        );
        assert_eq!(
            shell.document(),
            said(notice::Notice::error(
                "command",
                "Unknown command. Try /help."
            ))
        );

        // A prompt in hand: refused at once, nothing asked.
        shell.route_bytes(b"slow turn please\r");
        let _ = shell.picks_up();
        let _ = shell.document();
        shell.route_bytes(b"/fork\r");
        assert!(shell.sent.try_recv().is_err(), "a fork was asked mid-turn");
        assert_eq!(
            shell.document(),
            said(notice::Notice::neutral("session", FORK_BUSY))
        );
    }

    #[test]
    fn enter_forks_before_the_selected_prompt_and_the_fork_replays_with_its_two_lines() {
        // `fx-p5-effort-fork-fork-40x120-forked` and `.title`: the screen and
        // scrollback reset, `* session forked: <title>`, the plain line that
        // resumes the source, the kept turn, the prompt back in the composer
        // unsent, and the window called the fork.
        let mut shell = shell(40, 120);
        forked_menu(&mut shell, three_points());
        shell.route_bytes(b"\x1b[A\r");
        assert!(shell.fork_menu.is_none());
        assert_eq!(shell.picks_up(), TurnWork::Fork { before_turn: 2 });
        shell.work.give_back();
        assert!(
            shell.editor.is_empty(),
            "the composer filled before the fork"
        );
        let source = "1793751392050-7d3ce346fd20313d";
        shell.apply(UiEvent::Forked {
            replay: replay(
                Some("first prompt alpha (fork)"),
                vec![saved(
                    "first prompt alpha",
                    vec![HydratedStep::Text("ALPHA answer.".to_string())],
                    0,
                    Some(40),
                )],
            ),
            source: source.to_string(),
        });
        assert!(shell.owes_wipe());
        let document = shell.document();
        assert_eq!(
            document[..5],
            [
                "* session forked: first prompt alpha (fork)".to_string(),
                String::new(),
                format!("original session xfx --resume {source}"),
                String::new(),
                format!("{RAIL} {BOLD}first prompt alpha"),
            ],
            "{document:?}"
        );
        assert_eq!(shell.editor.text(), "second prompt beta");
        assert!(shell.sent.try_recv().is_err(), "the prompt was sent");
        assert_eq!(
            shell.take_title().as_deref(),
            Some("first prompt alpha (fork)")
        );
    }

    #[test]
    fn a_fork_that_lands_under_a_search_keeps_its_prompt_out_of_it() {
        // The fork is the runtime's, so a surface whose search is the
        // composer can open between the Enter that chose it and the fork
        // landing: recalled and sent, as any command can. Escape clears the
        // search; the prompt the fork hands back is the composer's draft
        // (`submitForkMenuSelection`'s `replace`,
        // `app_input_runtime.zig:1686@481104fd`), not a search. So it waits
        // for the surface to close -- every one [`Shell::composer_searched`]
        // names.
        let surfaces: [(&str, IsOpen); 6] = [
            ("/mcp", |shell| shell.mcp_menu.is_some()),
            ("/help", |shell| shell.help_menu.is_some()),
            ("/settings", |shell| shell.settings_menu.is_some()),
            ("/model", |shell| shell.model_menu.is_some()),
            ("/resume", |shell| shell.sessions.is_some()),
            ("/skills", |shell| {
                shell
                    .skills_menu
                    .as_ref()
                    .is_some_and(|menu| !menu.origin().is_mention())
            }),
        ];
        for (command, open) in surfaces {
            // A fixture with skills, so `/skills` has a list to search.
            let mut skilled = skilled();
            let shell: &mut Fixture = &mut skilled;
            land_fork_under(shell, command, open);
            assert_eq!(
                shell.editor.text(),
                "",
                "{command}: the fork's prompt went into the search"
            );
            escape(shell);
            assert!(!open(shell), "{command}: Escape left it up");
            assert_eq!(
                shell.editor.text(),
                "second prompt beta",
                "{command}: the prompt did not come back once it closed"
            );
            assert!(
                shell.sent.try_recv().is_err(),
                "{command}: the prompt was sent"
            );
        }
        // A search typed into after the fork landed is an edit, as one
        // before it is: the prompt is left out.
        let mut shell = fork_landed_under("/mcp", |shell| shell.mcp_menu.is_some());
        shell.route_bytes(b"zz");
        escape(&mut shell);
        assert!(shell.mcp_menu.is_none());
        assert_eq!(shell.editor.text(), "");
    }

    #[test]
    fn a_key_read_with_the_close_of_a_search_lands_after_the_forks_prompt() {
        // The prompt comes back before the next key of the same read, as a
        // C-p draft does (`settleModelPickerDraft`, after every input): a
        // Ctrl-C that closes `/mcp`'s menu and a letter read with it type the
        // letter after the prompt, not into an empty composer that would drop
        // it.
        let mut shell = fork_landed_under("/mcp", |shell| shell.mcp_menu.is_some());
        shell.consume(
            vec![Input::Action(Action::Cancel), Input::Text('x')],
            Instant::now(),
        );
        assert!(shell.mcp_menu.is_none());
        assert_eq!(shell.editor.text(), "second prompt betax");
    }

    #[test]
    fn a_held_forks_prompt_never_replaces_text_and_a_reset_drops_it() {
        // Once no search has the composer, the prompt goes only into an
        // empty one. A line recalled while the fork is on its way (a recall
        // is no edit) and lent to C-p's model menu comes back when the menu
        // closes: it is the user's draft, and the prompt is left out rather
        // than written over it.
        let mut shell = shell(40, 120);
        shell.route_bytes(b"/version\r");
        let _ = shell.document();
        forked_menu(&mut shell, three_points());
        shell.route_bytes(b"\x1b[A\r");
        assert_eq!(shell.picks_up(), TurnWork::Fork { before_turn: 2 });
        shell.work.give_back();
        recall_until(&mut shell, "/version");
        shell.route_bytes(&[0x10]);
        assert!(shell.model_menu.is_some(), "C-p opened no model menu");
        shell.apply(UiEvent::Forked {
            replay: replay(Some("first prompt alpha (fork)"), Vec::new()),
            source: "1793751392050-7d3ce346fd20313d".to_string(),
        });
        assert_eq!(shell.editor.text(), "", "the prompt went into the search");
        escape(&mut shell);
        assert!(shell.model_menu.is_none());
        assert_eq!(
            shell.editor.text(),
            "/version",
            "the prompt replaced the draft"
        );
        assert!(shell.fork_prompt_held.is_none());
        // A reset drops a held prompt with the conversation it was about.
        let mut shell = fork_landed_under("/mcp", |shell| shell.mcp_menu.is_some());
        shell.reset_session();
        shell.mcp_menu = None;
        shell.settle_fork_prompt();
        assert_eq!(shell.editor.text(), "");
    }

    /// Whether a surface a case opens is up.
    type IsOpen = fn(&Shell) -> bool;

    /// `command` run once and closed, then a fork chosen, `command` recalled
    /// and sent while the fork is on its way, and the fork landed under the
    /// surface it opened (`open`).
    fn fork_landed_under(command: &str, open: IsOpen) -> Fixture {
        let mut shell = shell(40, 120);
        land_fork_under(&mut shell, command, open);
        shell
    }

    /// [`fork_landed_under`], over a fixture of the case's own.
    fn land_fork_under(shell: &mut Fixture, command: &str, open: IsOpen) {
        // `/skills` opens its menu once the list it asked for lands.
        let landed = |shell: &mut Fixture| {
            if command == "/skills" {
                skills_landed(shell);
            }
        };
        shell.route_bytes(format!("{command}\r").as_bytes());
        landed(shell);
        assert!(open(shell), "{command} opened nothing");
        taken_up(shell);
        escape(shell);
        assert!(!open(shell));
        forked_menu(shell, three_points());
        shell.route_bytes(b"\x1b[A\r");
        assert_eq!(shell.picks_up(), TurnWork::Fork { before_turn: 2 });
        shell.work.give_back();
        recall_until(shell, command);
        shell.route_bytes(b"\r");
        landed(shell);
        assert!(open(shell), "the recalled {command} opened nothing");
        taken_up(shell);
        shell.apply(UiEvent::Forked {
            replay: replay(Some("first prompt alpha (fork)"), Vec::new()),
            source: "1793751392050-7d3ce346fd20313d".to_string(),
        });
        assert!(open(shell), "the fork closed {command}");
    }

    #[test]
    fn a_ctrl_p_model_menu_opened_and_closed_with_no_edit_keeps_the_forks_prompt() {
        // C-p needs no line, so it opens the model menu while a fork is on
        // its way, lending the draft -- empty -- to the menu
        // (`openModelPickerShortcut`, `app_input_runtime.zig:2356-2375`).
        // Giving it back is no edit of the user's: the fork's prompt, landed
        // under the menu or after it, comes back once the composer is free.
        for lands_under_the_menu in [true, false] {
            let mut shell = shell(40, 120);
            forked_menu(&mut shell, three_points());
            shell.route_bytes(b"\x1b[A\r");
            assert_eq!(shell.picks_up(), TurnWork::Fork { before_turn: 2 });
            shell.work.give_back();
            shell.route_bytes(&[0x10]);
            assert!(shell.model_menu.is_some(), "C-p opened no model menu");
            let forked = || UiEvent::Forked {
                replay: replay(Some("first prompt alpha (fork)"), Vec::new()),
                source: "1793751392050-7d3ce346fd20313d".to_string(),
            };
            if lands_under_the_menu {
                shell.apply(forked());
                assert_eq!(shell.editor.text(), "", "the prompt went into the search");
            }
            escape(&mut shell);
            assert!(shell.model_menu.is_none());
            if !lands_under_the_menu {
                shell.apply(forked());
            }
            assert_eq!(
                shell.editor.text(),
                "second prompt beta",
                "landed under the menu: {lands_under_the_menu}"
            );
            assert!(shell.sent.try_recv().is_err(), "the prompt was sent");
        }
    }

    /// Whatever opening a surface handed the runtime (`/resume`'s listing),
    /// taken up and its place given back.
    fn taken_up(shell: &mut Fixture) {
        while shell.sent.try_recv().is_ok() {
            shell.work.give_back();
        }
    }

    #[test]
    fn a_fork_prompt_held_under_the_session_picker_is_dropped_by_the_resume_an_escape_left_running()
    {
        // Escape takes the picker down while the resume it asked for runs (a
        // switch, `resume_selected`). The prompt held under the picker is the
        // forked conversation's: the session the resume lands in must not get
        // it as its draft, whether the Escape came first or the resume did.
        use super::super::session_picker::{ListedSession, Listing};
        let mut shell = fork_landed_under("/resume", |shell| shell.sessions.is_some());
        let session = |id: &str, title: &str| ListedSession {
            id: id.to_string(),
            title: Some(title.to_string()),
            workspace: "/x/work".to_string(),
            updated_at_ms: 0,
            turns: 1,
        };
        shell.apply(UiEvent::Sessions(Some(Listing {
            current: vec![
                session("b", "second question beta"),
                session("a", "first question alpha"),
            ],
            all: Vec::new(),
            now_ms: 0,
        })));
        shell.route_bytes(b"\x1b[B\r");
        assert_eq!(shell.picks_up(), TurnWork::Resume("a".to_string()));
        shell.work.give_back();
        escape(&mut shell);
        assert!(shell.sessions.is_none(), "Escape left the picker up");
        assert_eq!(
            shell.editor.text(),
            "",
            "the forked conversation's prompt came back over a resume in flight"
        );
        shell.apply(UiEvent::Resumed(replay(
            Some("first question alpha"),
            Vec::new(),
        )));
        shell.settle_input(Instant::now() + Decoder::ESC_TIMEOUT);
        assert_eq!(
            shell.editor.text(),
            "",
            "the forked conversation's prompt became the resumed session's draft"
        );
        assert!(shell.sent.try_recv().is_err(), "the prompt was sent");
    }

    #[test]
    fn a_fork_still_on_its_way_when_another_session_is_resumed_brings_no_prompt_to_it() {
        // The same switch with the fork landing after the resume was asked
        // for and the picker taken down: the runtime makes the fork first and
        // the resume then replaces it, so the fork's prompt is never the
        // resumed session's draft.
        use super::super::session_picker::{ListedSession, Listing};
        let mut shell = shell(40, 120);
        shell.route_bytes(b"/resume\r");
        taken_up(&mut shell);
        escape(&mut shell);
        forked_menu(&mut shell, three_points());
        shell.route_bytes(b"\x1b[A\r");
        assert_eq!(shell.picks_up(), TurnWork::Fork { before_turn: 2 });
        shell.work.give_back();
        recall_until(&mut shell, "/resume");
        shell.route_bytes(b"\r");
        taken_up(&mut shell);
        shell.apply(UiEvent::Sessions(Some(Listing {
            current: vec![ListedSession {
                id: "a".to_string(),
                title: Some("first question alpha".to_string()),
                workspace: "/x/work".to_string(),
                updated_at_ms: 0,
                turns: 1,
            }],
            all: Vec::new(),
            now_ms: 0,
        })));
        shell.route_bytes(b"\r");
        assert_eq!(shell.picks_up(), TurnWork::Resume("a".to_string()));
        shell.work.give_back();
        escape(&mut shell);
        assert!(shell.sessions.is_none());
        shell.apply(UiEvent::Forked {
            replay: replay(Some("first prompt alpha (fork)"), Vec::new()),
            source: "1793751392050-7d3ce346fd20313d".to_string(),
        });
        shell.apply(UiEvent::Resumed(replay(
            Some("first question alpha"),
            Vec::new(),
        )));
        shell.settle_input(Instant::now() + Decoder::ESC_TIMEOUT);
        assert_eq!(
            shell.editor.text(),
            "",
            "the fork's prompt became the resumed session's draft"
        );
        assert!(shell.sent.try_recv().is_err(), "the prompt was sent");
    }

    #[test]
    fn a_fork_prompt_held_under_the_session_picker_does_not_follow_a_resume_into_another_session() {
        // `/resume` recalled and sent while the fork is on its way: the picker
        // opens, the fork lands under it and its prompt is held. The user
        // then resumes another session. The prompt is the forked
        // conversation's, so it never becomes the resumed session's draft --
        // not when the resume lands, and not on the tick after it.
        use super::super::session_picker::{ListedSession, Listing};
        let mut shell = fork_landed_under("/resume", |shell| shell.sessions.is_some());
        let session = |id: &str, title: &str| ListedSession {
            id: id.to_string(),
            title: Some(title.to_string()),
            workspace: "/x/work".to_string(),
            updated_at_ms: 0,
            turns: 1,
        };
        shell.apply(UiEvent::Sessions(Some(Listing {
            current: vec![
                session("b", "second question beta"),
                session("a", "first question alpha"),
            ],
            all: Vec::new(),
            now_ms: 0,
        })));
        shell.route_bytes(b"\x1b[B\r");
        assert_eq!(shell.picks_up(), TurnWork::Resume("a".to_string()));
        shell.work.give_back();
        shell.apply(UiEvent::Resumed(replay(
            Some("first question alpha"),
            Vec::new(),
        )));
        assert!(shell.sessions.is_none());
        shell.settle_input(Instant::now() + Decoder::ESC_TIMEOUT);
        assert_eq!(
            shell.editor.text(),
            "",
            "the forked conversation's prompt became the resumed session's draft"
        );
        assert!(shell.sent.try_recv().is_err(), "the prompt was sent");
    }

    #[test]
    fn a_fork_before_the_first_prompt_leaves_its_line_over_the_composer_and_a_card_under_a_gap() {
        // `fx-p5-effort-fork-fork-empty-40x120-forked`: nothing under the
        // plain line but the composer; `-fork-continue-…-continued`: a blank
        // row between it and the card the next prompt writes.
        let mut shell = shell(40, 120);
        forked_menu(&mut shell, vec![fork_point(1, "only prompt omega")]);
        shell.route_bytes(b"\r");
        assert_eq!(shell.picks_up(), TurnWork::Fork { before_turn: 1 });
        shell.work.give_back();
        shell.apply(UiEvent::Forked {
            replay: replay(Some("only prompt omega (fork)"), Vec::new()),
            source: "1793751463125-512691a6e5611d2f".to_string(),
        });
        let document = shell.document();
        assert_eq!(document.len(), 3, "{document:?}");
        assert_eq!(
            document[2],
            "original session xfx --resume 1793751463125-512691a6e5611d2f"
        );
        assert_eq!(shell.editor.text(), "only prompt omega");
        shell.route_bytes(b"\r");
        let _ = shell.picks_up();
        let document = shell.document();
        assert_eq!(
            document[..2],
            [String::new(), format!("{RAIL} {BOLD}only prompt omega")],
            "{document:?}"
        );
    }

    #[test]
    fn a_panel_over_a_forks_plain_line_keeps_a_blank_row_above_it_until_it_closes() {
        // `fx-p5-effort-fork-fork-edge-40x120-status-empty`: `/status` over a
        // fork made before the first prompt -- `original session …`, a blank
        // row, then the panel's rule; `-fork-of-empty`: once it closes, the
        // composer is under the line again with nothing between. Upstream's
        // modal footer asks its frame for one blank row above it
        // (`top_gap_rows`, `surface_frame.zig:686@481104fd`), which the frame
        // takes the larger of with the transcript's own (`idle_gap`,
        // `frame_layout.zig:392`).
        let mut shell = shell(40, 120);
        forked_menu(&mut shell, vec![fork_point(1, "only prompt omega")]);
        shell.route_bytes(b"\r");
        assert_eq!(shell.picks_up(), TurnWork::Fork { before_turn: 1 });
        shell.work.give_back();
        shell.apply(UiEvent::Forked {
            replay: replay(Some("only prompt omega (fork)"), Vec::new()),
            source: "1793751463125-512691a6e5611d2f".to_string(),
        });
        let document = shell.document();
        shell.document_landed(u32::try_from(document.len()).expect("three rows"));
        shell.route_bytes(&[0x15]);
        assert!(shell.editor.is_empty());

        shell.open_info_panel(fx_status_panel());
        assert_eq!(shell.geometry.input_rows(), 0, "the composer kept its row");
        assert_eq!(shell.geometry.gap, 1, "no blank row above the panel");
        let rows = shell.band_rows();
        assert_eq!(rows.len(), usize::from(shell.geometry.band_rows()));
        assert_eq!(rows[0], "", "the band's top is not blank");
        assert_eq!(rows[1], divider(120), "the panel's rule is not under it");
        assert_eq!(
            shell.geometry.band_top(),
            4,
            "the blank row is not under the document's three rows"
        );
        assert_eq!(
            shell.geometry.panel_first() - 1,
            5,
            "the rule is not a row below the blank"
        );

        escape(&mut shell);
        assert!(shell.info_panel.is_none());
        assert_eq!(shell.geometry.gap, 0, "the blank row outlived the panel");
        assert_eq!(shell.band_rows()[0], composer_row(""));
        assert_eq!(shell.geometry.band_top(), 4, "the composer left the line");
    }

    #[test]
    fn a_block_that_lands_under_the_panel_ends_the_document_blank_and_takes_the_row_back() {
        // The two gaps are one: the larger of the band's and the document's
        // (`@max(transcript_gap, input.footer.top_gap_rows)`,
        // `frame_layout.zig:392@481104fd`). A notice written while the panel
        // is up ends the document on its own blank row, so the band's goes.
        let mut shell = shell(40, 120);
        forked_menu(&mut shell, vec![fork_point(1, "only prompt omega")]);
        shell.route_bytes(b"\r");
        let _ = shell.picks_up();
        shell.work.give_back();
        shell.apply(UiEvent::Forked {
            replay: replay(Some("only prompt omega (fork)"), Vec::new()),
            source: "1793751463125-512691a6e5611d2f".to_string(),
        });
        let landed = shell.document().len();
        shell.document_landed(u32::try_from(landed).expect("three rows"));
        shell.open_info_panel(fx_status_panel());
        assert_eq!(shell.geometry.gap, 1);

        shell.announce(notice::Notice::neutral("system", "said under the panel"));
        let more = shell.document();
        assert_eq!(more.last().map(String::as_str), Some(""), "{more:?}");
        shell.document_landed(u32::try_from(landed + more.len()).expect("rows"));
        assert_eq!(shell.geometry.gap, 0, "two blank rows over the panel");
        assert_eq!(shell.band_rows()[0], divider(120));
        assert_eq!(
            usize::from(shell.geometry.band_top()),
            landed + more.len() + 1,
            "the panel is not under the notice's blank row"
        );
    }

    /// A fork before the first prompt, landed: the document ends on its plain
    /// `original session …` line, with no blank row under it.
    fn forked_before_the_first_prompt(shell: &mut Fixture) -> usize {
        forked_menu(shell, vec![fork_point(1, "only prompt omega")]);
        shell.route_bytes(b"\r");
        let _ = shell.picks_up();
        shell.work.give_back();
        shell.apply(UiEvent::Forked {
            replay: replay(Some("only prompt omega (fork)"), Vec::new()),
            source: "1793751463125-512691a6e5611d2f".to_string(),
        });
        let landed = shell.document().len();
        shell.document_landed(u32::try_from(landed).expect("three rows"));
        shell.route_bytes(&[0x15]);
        assert!(!shell.transcript.ends_blank(), "the plain line ended blank");
        landed
    }

    #[test]
    fn a_question_over_a_forks_plain_line_keeps_the_blank_row_and_names_its_controls_row() {
        // An approval, a model's question and a rule's confirmation take the
        // composer's rows like the panel, so upstream's footer asks the same
        // blank row above them (`modal_active`, `surface_frame.zig:392-395`,
        // `:686@481104fd`). And the row the readiness receipt names for the
        // last choice is the row the band really paints it on.
        let mut shell = shell(40, 120);
        let landed = forked_before_the_first_prompt(&mut shell);
        shell.apply(UiEvent::Approval(question(asked())));
        assert!(matches!(shell.slot(), Some(Slot::Question(_))));
        assert_eq!(shell.geometry.input_rows(), 0, "the composer kept its row");
        assert_eq!(shell.geometry.gap, 1, "no blank row above the question");
        let rows = uncoloured_rows(&shell.band_rows());
        assert_eq!(rows.len(), usize::from(shell.geometry.band_rows()));
        assert_eq!(rows[0], "", "the band's top is not blank: {rows:?}");
        assert_eq!(
            rows[1],
            uncoloured(&divider(120)),
            "the rule is not under it"
        );
        assert_eq!(
            usize::from(shell.geometry.band_top()),
            landed + 1,
            "the blank row is not under the plain line"
        );
        let painted = rows
            .iter()
            .rposition(|row| row.contains("3  Don't apply"))
            .expect("the refusal is a row of the band");
        shell.intend_approval();
        assert_eq!(
            shell.readiness.pending_control_row(),
            Some(shell.geometry.band_top() + u16::try_from(painted).expect("a small index")),
            "the receipt names a row the last choice is not on"
        );
        assert_eq!(
            shell.geometry.panel_first(),
            shell.geometry.band_top() + 2,
            "the panel is not under the blank row and the rule"
        );
    }

    #[test]
    fn the_receipt_names_the_painted_row_of_the_last_choice_at_every_height_with_and_without_the_gap(
    ) {
        // Review FK-GAPb (gpt6, nice-to-have 2): the pin above is one roomy
        // screen at gap 1. Every height from the shortest band up to a roomy
        // one, under a document that ends blank (no gap) and under a fork's
        // plain line (the gap, while the screen has a row for it): wherever
        // the question is inline, the receipt names the row its last choice
        // is painted on, and a delivered frame makes it ready.
        let mut inline = [0usize; 2];
        let mut tightest = [None::<u16>; 2];
        for rows in layout::MIN_ROWS..=40 {
            for forked in [false, true] {
                let mut case = shell(rows, 80);
                if forked {
                    let _ = forked_before_the_first_prompt(&mut case);
                }
                case.apply(UiEvent::Approval(question(asked())));
                if case.panel.is_none() {
                    continue;
                }
                inline[usize::from(forked)] += 1;
                if !forked {
                    // The welcome line ends blank, so no gap of the band's:
                    // the half of this case that is about gap 0.
                    assert_eq!(case.geometry.gap, 0, "{rows}x80: a gap under a blank tail");
                }
                tightest[usize::from(forked)].get_or_insert(rows);
                let painted = uncoloured_rows(&case.band_rows())
                    .iter()
                    .rposition(|row| row.contains("3  Don't apply"))
                    .expect("the refusal is a row of the band");
                let painted = case.geometry.band_top() + u16::try_from(painted).expect("small");
                assert!(
                    painted <= rows,
                    "{rows}x80 forked={forked}: painted below the screen"
                );
                case.intend_approval();
                assert_eq!(
                    case.readiness.pending_control_row(),
                    Some(painted),
                    "{rows}x80 forked={forked} gap={}: the receipt names another row",
                    case.geometry.gap
                );
                delivered(&mut case);
                assert!(
                    case.readiness.ready(ApprovalId(1), 80, rows),
                    "{rows}x80 forked={forked}: a delivered frame is not ready"
                );
            }
        }
        assert!(
            inline[0] > 0 && inline[1] > 0,
            "no inline question: {inline:?}"
        );
        // The fit boundary: a question is inline only on a screen that holds
        // it with a turn's row and its blank ([`layout::fits_approval`]), so
        // the fork's blank row always has room there and does not move the
        // boundary; one row shorter, the question goes to a screen of its own.
        assert_eq!(tightest[0], tightest[1], "the blank row moved the boundary");
        let tight = tightest[1].expect("an inline question after the fork");
        assert!(
            tight > layout::MIN_ROWS,
            "no height below the boundary was tried"
        );
        let mut short = shell(tight, 80);
        let _ = forked_before_the_first_prompt(&mut short);
        short.apply(UiEvent::Approval(question(asked())));
        assert_eq!(short.geometry.gap, 1, "{tight}x80 dropped the blank row");
        let mut shorter = shell(tight - 1, 80);
        let _ = forked_before_the_first_prompt(&mut shorter);
        shorter.apply(UiEvent::Approval(question(asked())));
        assert!(
            shorter.panel.is_none(),
            "{}x80 put the question inline",
            tight - 1
        );
    }

    #[test]
    fn a_rule_confirmation_over_a_forks_plain_line_keeps_the_blank_row() {
        let (_home, _workspace, _rules, mut shell) = remembering_shell();
        let landed = forked_before_the_first_prompt(&mut shell);
        // The runtime has made the fork: the two pieces of work it took, the
        // `/fork`'s question and the switch.
        let _ = shell.work.title_desk().worked_through(2);
        shell.route_bytes(
            b"/permissions remember allow write_file {\"path\":\"a.txt\",\"content\":\"x\"}\r",
        );
        assert!(
            matches!(shell.slot(), Some(Slot::Rule(_))),
            "no confirmation: {:?}",
            shell.document()
        );
        assert_eq!(shell.geometry.gap, 1, "no blank row above the confirmation");
        let rows = confirmation_rows(&shell);
        assert_eq!(rows[0], "", "{rows:?}");
        assert!(rows[1].starts_with('\u{2500}'), "{rows:?}");
        assert_eq!(usize::from(shell.geometry.band_top()), landed + 1);
        escape(&mut shell);
        assert!(shell.rule_confirm.is_none());
        assert_eq!(
            shell.geometry.gap, 0,
            "the blank row outlived the confirmation"
        );
    }

    #[test]
    fn a_fork_that_failed_says_so_and_a_typed_composer_is_not_refilled() {
        // `Unable to fork the session.` (`app_input_runtime.zig:1670-1678@481104fd`).
        let mut shell = shell(40, 120);
        forked_menu(&mut shell, three_points());
        shell.route_bytes(b"\r");
        assert_eq!(shell.picks_up(), TurnWork::Fork { before_turn: 3 });
        shell.work.give_back();
        shell.apply(UiEvent::ForkFailed);
        assert_eq!(
            shell.document(),
            said(notice::Notice::error("session", FORK_FAILED))
        );
        assert!(shell.editor.is_empty());
        // What was typed while the fork was being made is the user's.
        forked_menu(&mut shell, three_points());
        shell.route_bytes(b"\r");
        let _ = shell.picks_up();
        shell.work.give_back();
        shell.route_bytes(b"mine");
        shell.apply(UiEvent::Forked {
            replay: replay(Some("t (fork)"), Vec::new()),
            source: "1793751463125-512691a6e5611d2f".to_string(),
        });
        assert_eq!(shell.editor.text(), "mine");
    }

    #[test]
    fn a_fork_writes_nothing_a_terminal_would_obey() {
        // A prompt, a title and an id are read back off a log: the channel
        // spells them inert, and the shell holds without it. An id that is not
        // one writes no line at all.
        let hostile = "evil\u{1b}]2;owned\u{7}\u{1b}[2J\u{9b}31m";
        // Applied as written, past the channel's own spelling
        // (`bridge`'s `a_forks_prompts_title_and_source_id_are_made_inert`):
        // the shell's rows hold on their own.
        let event = UiEvent::ForkPoints(ForkPoints::Points(vec![fork_point(
            1,
            &format!("p {hostile}"),
        )]));
        let mut shell = shell(40, 120);
        shell.route_bytes(b"/fork\r");
        let _ = shell.picks_up();
        shell.work.give_back();
        shell.apply(event);
        for row in menu(&shell) {
            assert!(
                !visible_text(&row).contains(['\u{1b}', '\u{7}', '\u{9b}']),
                "{row:?}"
            );
        }
        shell.route_bytes(b"\r");
        let _ = shell.picks_up();
        shell.work.give_back();
        let forked = UiEvent::Forked {
            replay: replay(Some(&format!("t {hostile} (fork)")), Vec::new()),
            source: format!("1793751463125-512691a6e5611d2f{hostile}"),
        };
        shell.apply(forked);
        let document = shell.document();
        assert!(
            document
                .iter()
                .all(|row| !row.contains(['\u{1b}', '\u{7}', '\u{9b}'])),
            "{document:?}"
        );
        assert!(
            !document
                .iter()
                .any(|row| row.starts_with("original session")),
            "{document:?}"
        );
        assert!(!shell.editor.text().contains(['\u{1b}', '\u{7}', '\u{9b}']));
        assert!(shell
            .take_title()
            .is_some_and(|title| !title.contains(['\u{1b}', '\u{7}', '\u{9b}'])));
    }

    #[test]
    fn the_fork_menu_stays_under_a_first_ctrl_c_and_says_the_next_one_leaves() {
        // `composeForkMenuHintRow`'s `ctrl_c_pending`
        // (`input_presentation.zig:704-712@481104fd`).
        let mut shell = shell(40, 120);
        forked_menu(&mut shell, three_points());
        let now = Instant::now();
        shell.consume(vec![Input::Action(Action::Cancel)], now);
        shell.settle_band(now);
        assert!(shell.fork_menu.is_some(), "a first Ctrl-C closed the menu");
        assert_eq!(
            shell.band_rows().last().cloned(),
            Some(format!(
                "{}{EXIT_ARMED}{}",
                PALETTE.statusline(),
                PALETTE.reset()
            ))
        );
        assert!(!shell.leaving());
    }

